(window.PF_CAT_SHARD=window.PF_CAT_SHARD||{})["76458"]={"2588":{"i":"2588","entryRequirements":"Applicants must have one of the following, or equivalent:\n\r\n1. A recognized bachelor degree in the same or similar discipline , with merit achievement deemed to be an average grade of B- or higher in all Level 7 courses; OR\n\r\n2. A professional qualifications in a relevant discipline, recognized as being equivalent to merit achievement in a bachelor degree.\n\n\n\r\nEnglish language requirements for international students:\n\r\nApplicants must have: \n\r\n*\tgained NCEA level 3 and met New Zealand university entrance requirements; or \n\r\n*\tclear evidence that they satisfy one of the criteria for existing English proficiency listed on NZQA's website at: \nhere\n \n\r\n*\tachieved, within the preceding two years, at least one of the below: \n\r\no\tCompletion of either the NZCEL (Academic) (Level 5) An overall IELTS band score (Academic Format) of 6.5 with no band score lower than 6; \n\r\no\tAn overall TOEFL pBT (Paper-based Test) score of 590 (plus essay TWE of 5.5) OR an overall TOEFL iBT (Internet-based Test) score of 79 (plus writing score of 21); \n\r\no\tFirst Certificate in English (FCE) with a pass at Grade A OR Certificate in Advanced English (CAE) with a score of 58 or higher OR Certificate of Proficiency in English (CPE) with a score of 45 or higher under the Cambridge International standard tests of English as a foreign language \n\r\no\tPearson Test of English PToE (Academic) with a score of 58\n\r\no\tCity & Guilds Internal English for Speakers of Other Languages (IESOL) C1 Expert with a score of 42.","strategicPurposeStatement":"This qualification is designed for learners wishing to develop higher levels of academic ability and creative practice based research capability in a collaborative multi-disciplinary learning environment. The qualification aims to meet the workplace demands of creative and cultural industries for flexible individuals with a broader range of skills and an ability to collaborate across disciplines. The qualification fosters independence of thought, autonomy of action, creativity and originality as well as collaborative and reflective capacities and attitudes among learners.","graduateProfile":"Graduates of the Master of Creative Practice will have: an awareness of current and available scholarship, advanced knowledge and technologies relevant to their specialist field of enquiry or professional practice and the ability to remain current within their discipline; the ability to apply knowledge to new and existing situations and innovate their practice in order to contribute to and advance their respective industries; the ability to engage in rigorous intellectual analysis, criticism and problem-solving; the capacity for cross-cultural communication and multi-cultural inclusivity; the ability to work productively across functional and/or disciplinary boundaries and within changing environments; the ability to lead creative projects successfully within a practice environment and to lead creative teams where appropriate. the ability to plan, execute and complete research within the context of their own creative practice; an advanced mastery of theory and practice in a specialist area of creative practice.","educationPathway":"-","developedBy":"Manukau Institute of Technology and Unitec - Unitec","qualityAssuredBy":"New Zealand Qualifications Authority","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=2588"},"2589":{"i":"2589","entryRequirements":"Applicants must have one of the following, or equivalent:\n\r\n1. A recognized bachelor degree in the same or similar discipline , with merit achievement deemed to be an average grade of B- or higher in all Level 7 courses; OR\n\r\n2. A professional qualification in a relevant discipline, recognized as being equivalent to merit achievement in a bachelor degree.\n\n\n\r\nEnglish language requirements for international students:\n\r\nApplicants must have: \n\r\n*\tgained NCEA level 3 and met New Zealand university entrance requirements; or \n\r\n*\tclear evidence that they satisfy one of the criteria for existing English proficiency listed on NZQA's website at: \nhere\n \n\r\n*\tachieved, within the preceding two years, at least one of the below: \n\r\no\tCompletion of either the NZCEL (Academic) (Level 5) An overall IELTS band score (Academic Format) of 6.5 with no band score lower than 6; \n\r\no\tAn overall TOEFL pBT (Paper-based Test) score of 590 (plus essay TWE of 5.5) OR an overall TOEFL iBT (Internet-based Test) score of 79 (plus writing score of 21); \n\r\no\tFirst Certificate in English (FCE) with a pass at Grade A OR Certificate in Advanced English (CAE) with a score of 58 or higher OR Certificate of Proficiency in English (CPE) with a score of 45 or higher under the Cambridge International standard tests of English as a foreign language \n\r\no\tPearson Test of English PToE (Academic) with a score of 58\n\r\no\tCity & Guilds Internal English for Speakers of Other Languages (IESOL) C1 Expert with a score of 42.","strategicPurposeStatement":"This qualification is designed for learners wishing to enhance their professional practice and career development in a collaborative multi-disciplinary learning environment. The qualification aims to meet the workplace demand of creative and cultural industries for professionals who can combine discipline specific expertise with the capacity to work collaboratively across disciplines. The qualification fosters the acquisition of additional creative and professional skills that will enhance the learners professional career.","graduateProfile":"The Postgraduate Certificate in Creative Practice will produce graduates who have: an awareness of current and available scholarship, advanced knowledge and technologies relevant to their specialist field of enquiry or professional practice and the ability to remain current within their discipline; the ability to apply knowledge to new and existing situations and innovate their practice in order to contribute to and advance their respective industries; the ability to work productively across functional and/or disciplinary boundaries and within changing environments; the capacity for cross-cultural communication and multi-cultural inclusivity;","educationPathway":"n/a","developedBy":"Manukau Institute of Technology and Unitec - Unitec","qualityAssuredBy":"New Zealand Qualifications Authority","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=2589"},"2590":{"i":"2590","entryRequirements":"Applicants must have one of the following, or equivalent:\n\r\n1. A recognized bachelor degree in the same or similar discipline , with merit achievement deemed to be an average grade of B- or higher in all Level 7 courses; OR\n\r\n2. A professional qualifications in a relevant discipline, recognized as being equivalent to merit achievement in a bachelor degree.\n\n\n\r\nEnglish language requirements for international students:\n\r\nApplicants must have: \n\r\n*\tgained NCEA level 3 and met New Zealand university entrance requirements; or \n\r\n*\tclear evidence that they satisfy one of the criteria for existing English proficiency listed on NZQA's website at: \nhere\n \n\r\n*\tachieved, within the preceding two years, at least one of the below: \n\r\no\tCompletion of either the NZCEL (Academic) (Level 5) An overall IELTS band score (Academic Format) of 6.5 with no band score lower than 6; \n\r\no\tAn overall TOEFL pBT (Paper-based Test) score of 590 (plus essay TWE of 5.5) OR an overall TOEFL iBT (Internet-based Test) score of 79 (plus writing score of 21); \n\r\no\tFirst Certificate in English (FCE) with a pass at Grade A OR Certificate in Advanced English (CAE) with a score of 58 or higher OR Certificate of Proficiency in English (CPE) with a score of 45 or higher under the Cambridge International standard tests of English as a foreign language \n\r\no\tPearson Test of English PToE (Academic) with a score of 58\n\r\no\tCity & Guilds Internal English for Speakers of Other Languages (IESOL) C1 Expert with a score of 42.","strategicPurposeStatement":"This qualification is designed for learners wishing to update, extend and apply their existing academic, practical and/or creative skills in a collaborative multi-disciplinary learning environment. The qualification aims to meet the workplace demands of creative and cultural industries for flexible individuals with a broad range of skills and an ability to collaborate across disciplines. The qualification fosters the development of versatile professionals who have the necessary technical and creative expertise to engage independently in a broad range of activities related to the wider creative industries.","graduateProfile":"Graduates of the Postgraduate Diploma in  Creative Practice will have: an awareness of current and available scholarship, advanced knowledge and technologies relevant to their specialist field of enquiry or professional practice and the ability to remain current within their discipline; the ability to apply knowledge to new and existing situations and innovate their practice in order to contribute to and advance their respective industries; the ability to work productively across functional and/or disciplinary boundaries and within changing environments; the capacity for cross-cultural communication and multi-cultural inclusivity;\n\r\nthe ability to lead creative projects successfully within a practice environment and to lead creative teams where appropriate; the ability to engage in rigorous intellectual analysis, criticism and problem-solving;","educationPathway":"NA","developedBy":"Manukau Institute of Technology and Unitec - Unitec","qualityAssuredBy":"New Zealand Qualifications Authority","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=2590"},"3138":{"i":"3138","entryRequirements":"Minimum entry requirements are\n\r\n1. The Bachelor of Design (discipline endorsed) Level 7, or an equivalent qualification at bachelor level or above with an overall grade of B+ (75%) or higher in final year level 7 courses.\n\r\n2. Commencement of the honours study must occur within five years of the successful completion of the undergraduate degree. Exceptions require the approval of the postgraduate coordinator based on advice from the relevant academic leader and the supervisor.\n\r\n3. International entrants must demonstrate that they have equivalent experience/qualifications as domestic entrants, and, for those whose first language is not English, must provide evidence of English language competence of IELTS academic band score of 6.5 (overall) with no individual band less than 6.0, or equivalent.","strategicPurposeStatement":"The Bachelor of Design (Honours) provides students who have already achieved excellence in their undergraduate degree the opportunity to extend and deepen their knowledge and understanding of design research methods and professional design practices. Through advanced research and systematic engagement with contemporary thinking in their chosen field, they will develop an honours project which demonstrates research by design, addresses sustainability from multiple perspectives, is supported by a dissertation or equivalent, and presented in a public forum. Graduates will be prepared for further postgraduate study or employment in a design creative lead role.","graduateProfile":"Graduates of the Bachelor of Design (Honours) will be able to:\n\r\n* demonstrate an applied understanding of the historical and contemporary conventions of their field\n\r\n* engage with a range of design research methods\n\r\n* demonstrate intellectual independence, analytic rigour, and the ability to understand and evaluate new knowledge and ideas\n\r\n* incorporate critique to produce a proposal-based body of critically engaged applied design research expressed through a design outcome\n\r\n* reflect on the application of professional practices in a design studio or workplace environment\n\r\n* address sustainability from cultural, social, environmental and/or economic perspectives through their chosen project\n\r\n* acquire the ability to assess and evaluate the cultural, social, environmental and/or economic impact via completion of an impact assessment report\n\r\n* evaluate and articulate how their work is positioned within a wider context\n\r\n* produce a scholarly research document or equivalent that supports their chosen project\n\r\n* exhibit or present project findings in a public forum","educationPathway":"Further postgraduate study at level 9 and 10.","developedBy":"Otago Polytechnic","qualityAssuredBy":"New Zealand Qualifications Authority","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=3138"},"3139":{"i":"3139","entryRequirements":"Minimum entry requirements are \n\r\n1. The Bachelor of Design (discipline endorsed) Level 7, or an equivalent qualification at bachelor level in a related discipline, or equivalent documented professional experience. \n\r\n2. A physical or digital portfolio which demonstrates a range of creative work relevant to their field \n\r\n3. International entrants must demonstrate that they have equivalent experience/qualifications as domestic entrants, and, for those whose first language is not English, must provide evidence of English language competence of IELTS academic band score of 6.5 (overall) with no individual band less than 6.0, or equivalent.","strategicPurposeStatement":"Graduates of the Postgraduate Certificate in Design will extend and deepen their knowledge and understanding of design research methods and the professional design environment. Graduates will have completed an applied design project, which allows them to address sustainability from multiple perspectives and to position their work within a wider market context. This qualification prepares students for further postgraduate study, or for employment in a creative design or design management role.","graduateProfile":"Graduates of the Postgraduate Certificate in Design will be able to: \n\r\n* work independently to explore skills, techniques and ideas associated with an applied design project \n\r\n* analyse a range of information and incorporate critique to arrive at a resolved final design outcome \n\r\n* reflect on the application of professional practices in a design studio or workplace environment \n\r\n* address sustainability from cultural, social, environmental and/or economic perspectives \n\r\n* apply skills, techniques and ideas through an applied design project \n\r\n* evaluate how their work is positioned in a wider context \n\r\n* assess and evaluate the cultural, social, environmental and/or economic impact of a project","educationPathway":"Further postgraduate study at level 9 and 10.","developedBy":"Otago Polytechnic","qualityAssuredBy":"New Zealand Qualifications Authority","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=3139"},"3140":{"i":"3140","entryRequirements":"Minimum entry requirements are\n\r\n1. The Bachelor of Design (discipline endorsed) Level 7, or an equivalent qualification at bachelor level in a related discipline, or equivalent documented professional experience.\n\r\n2. A physical or digital portfolio which demonstrates a range of creative work relevant to their field\n\r\n3. International entrants must demonstrate that they have equivalent experience/qualifications as domestic entrants, and, for those whose first language is not English, must provide evidence of English language competence of IELTS academic band score of 6.5 (overall) with no individual band less than 6.0, or equivalent.","strategicPurposeStatement":"Graduates of the Postgraduate Diploma in Design will extend and deepen their knowledge and understanding of design research methods and professional design practices. Through applied design projects students will address sustainability and consider impact from multiple perspectives, and position their work in a wider market context. The final project is supported by a body of writing and presented in a public forum. This qualification prepares students for further postgraduate study or a career in design or design management.","graduateProfile":"Graduates of the Postgraduate Diploma in Design will be able to:\n\r\n* work independently to explore skills, techniques and ideas associated with an applied design project\n\r\n* demonstrate an applied understanding of the historical and contemporary conventions of their field\n\r\n* engage with a range of design research methods to develop a draft proposal for an applied design research project\n\r\n* analyse sophisticated information and incorporate critique to arrive at a resolved final design outcome\n\r\n* reflect on the application of professional practices in a design studio or workplace environment\n\r\n* produce a proposal-based body of critically engaged applied design research expressed through a design outcome\n\r\n* address sustainability from cultural, social, environmental and/or economic perspectives\n\r\n* assess and evaluate the cultural, social, environmental and/or economic impact of a project\n\r\n* produce a scholarly research document or equivalent that supports a chosen project\n\r\n* evaluate and articulate how their work is positioned within a wider context\n\r\n* exhibit or present their project in a public forum","educationPathway":"Further postgraduate study at level 9 and 10.","developedBy":"Otago Polytechnic","qualityAssuredBy":"New Zealand Qualifications Authority","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=3140"},"3141":{"i":"3141","entryRequirements":"Minimum entry requirements are \n\r\n1. The Bachelor of Design (Honours) at level 8, or the Postgraduate Diploma in Design at level 8 with an overall grade of B+ (75%) in Design Research Methods and Applied Design Project 2 or an equivalent postgraduate qualification of 120 credits in a related area. \n\r\n2. Exceptional applicants not meeting the entry requirements but with appropriate documented professional experience may also be considered. \n\r\n3. International entrants must demonstrate that they have equivalent experience/qualifications as domestic entrants, and, for those whose first language is not English, must provide evidence of English language competence of IELTS academic band score of 6.5 (overall) with no individual band less than 6.0, or equivalent.","strategicPurposeStatement":"Graduates of the Master of Design will demonstrate mastery of theoretically sophisticated subject matter through a body of scholarly creative work, which is presented in a public forum and supported by an exegesis or equivalent, or through a thesis, which could form the basis of scholarly journal articles. The work will respond to societal needs, address sustainability from multiple perspectives and be positioned within a wider framework of academic and applied research. This qualification prepares students for doctoral level study, an academic career or a lead design or design management role.","graduateProfile":"Graduates of the Master of Design will be able to: \n\r\n* demonstrate mastery of skills, techniques and methods associated with their discipline \n\r\n* analyse sophisticated information and incorporate critique to arrive at a resolved final design outcome or thesis \n\r\n* demonstrate a high order of skill in the planning, execution and completion of a piece of original research or creative scholarly work \n\r\n* address sustainability from cultural, social, environmental and/or economic perspectives through the body of creative work OR thesis \n\r\n* assess and evaluate the cultural, social, environmental and/or economic impact of a project or subject matter \n\r\n* confidently articulate the impact and contribution of their work in a wider context \n\r\n* exhibit or present their work in a local, national and/or international forum \n\r\n* craft sophisticated creative solutions and respond to professional challenges \n\r\n* apply the skills learned in this programme to new situations","educationPathway":"Further postgraduate study at level 9 and 10.","developedBy":"Otago Polytechnic","qualityAssuredBy":"New Zealand Qualifications Authority","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=3141"},"3201":{"i":"3201","entryRequirements":"TThe academic entry requirement for the THkT Poutiri-a-Rangi is one of the following:\n\r\n·\tan NZQF-listed undergraduate degree (or equivalent) in a creative practice field with a minimum of the equivalent to a B- (B Minus) average across the final year of study as per the EIT-specified 11-point achievement-based grading system;\n\r\nor\n\r\n·\tin the absence of the above, provisional admission on the basis of an evaluation of a portfolio of work;\n\r\nor\n\r\n·\tat the Dean's discretion, where an applicant's situation is compelling but not covered by the requirements listed above.","strategicPurposeStatement":"To provide an opportunity for students to create an effective and professional body of creative work, make it publicly available and speak professionally about that work based on in depth and broad research.","graduateProfile":"Graduates are able to contextualise their practice in relation to relevant communities and contemporary practice, research and critically analyse theories and philosophies for effective creative projects, create an effective and professional body of creative work.","educationPathway":"Masters degree.","developedBy":"Eastern Institute of Technology","qualityAssuredBy":"New Zealand Qualifications Authority","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=3201"},"3202":{"i":"3202","entryRequirements":"The academic entry requirement for the THkT Poutiriao is one of the following:\n\r\n·\tan NZQF-listed Bachelor's or higher level degree (or equivalent) in a creative practice field with a minimum of the equivalent to a B- (B Minus) average across the final year of study as per the EIT-specified 11-point achievement-based grading system;\n\r\nor\n\r\n·\tin the absence of the above, provisional admission on the basis of an evaluation of a portfolio of work;\n\r\nor\n\r\n·\tat the Dean's discretion, where an applicant's situation is compelling but not covered by the requirements listed above.","strategicPurposeStatement":"Provides an opportunity to apply an advanced body of knowledge derived from research to a body of publicly accessible creative work.","graduateProfile":"Graduates are able to contextualise their practice in relation to relevant communities and contemporary practice, research and critically analyse theories and philosophies for effective creative projects, create an effective and professional body of creative work which demonstrates mastery that develops, extends and refines prior professional practices, processes and knowledge.","educationPathway":"This Masters degree is likely to be an end point qualification, but it may be possible for students to progress to PhD.","developedBy":"Eastern Institute of Technology","qualityAssuredBy":"New Zealand Qualifications Authority","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=3202"},"3695":{"i":"3695","entryRequirements":"Honours Degree, Post Graduate Diploma, or equivalent.  \n\r\nMinimum entry for international students of IELTS (or equivalent) Level 6.5.","strategicPurposeStatement":"Students will develop skills and expertise in design theory and original research. Students will gain a computer graphic design qualification which enables a variety of employment opportunities in design and technology.","graduateProfile":"Candidates for this programme are required to undertake and complete a written thesis based on their research   \n\r\ninitiatives and prepare a body of work for final exhibition.   \n\r\nThey must possess an exceptional degree of motivation and a strong enthusiasm for design.","educationPathway":"PhD in related studies","developedBy":"Universal College of Learning (UCOL)","qualityAssuredBy":"New Zealand Qualifications Authority","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=3695"},"4102":{"i":"4102","entryRequirements":"Academic Requirements A Bachelor's degree in a relevant subject area. Alternative Requirements Applicants unable to evidence that they meet Academic Entry requirements, but who can demonstrate relevant skills and knowledge acquired through appropriate work or professional experience, may be approved for alternative entry. Additional Requirements Applicants are required to undertake course advisement with an Ara staff member and complete a for postgraduate study application form (refer Appendix 2.8). English Requirements If English is not the applicant's first language, applicants will need to provide a result from a test or qualification on the acceptable alternatives English Proficiency Outcomes Chart. Applicants who do not have evidence of English language skills and are a New Zealand citizen or permanent resident, may contact Ara for an assessment. IELTS 6.5 Academic (no lower than 6.0 in any subtest). Note: IELTS scores used must be taken from a single IELTS Test Report Form and are valid for two years from the date of the test. Applicants who have achieved NCEA Level 3 University Entrance requirements are not required to provide evidence of English language skills.","strategicPurposeStatement":"The aim of the Postgraduate Diploma in Creative Practice is to develop and apply advanced  \n\r\nknowledge of theories and worldviews, including Te Ao Māori, related to a domain of research and  \n\r\ncreative practice.  \n\r\nThe programme aims to prepare students for independent practice-based research knowledge  \n\r\nwithin a domain of practice, that extends the skills developed by a student's undergraduate study  \n\r\nor acquired through professional practice.  \n\r\nThis programme is intended for graduates from Ara or other institutions and current practitioners  \n\r\nwith a track record of independent creative practice outside of tertiary study. These may include  \n\r\nmusicians, dramatists, performing and visual artists, designers, film makers, writers, directors or  \n\r\nany others engaged in creative pursuits.","graduateProfile":"Graduates of this qualification will be able to:  \n\r\n1. Critique and communicate a systematic account of the relevant knowledge, principles, research  \n\r\nmethods and problem-solving techniques applicable to a specific domain of creative practice.  \n\r\n2. Demonstrate intellectual independence, critical thinking, analytic rigour and self-directed  \n\r\nlearning in the design and execution of a self-directed creative project.  \n\r\n3. Apply knowledge to practice-based research; analyse and develop arguments from primary  \n\r\nevidence.  \n\r\n4. Apply cross cultural perspectives which embrace understanding and engagement with  \n\r\nindigenous bodies of knowledge, practices and worldviews with a key focus on Te Ao Māori and  \n\r\nbicultural Aotearoa New Zealand.","educationPathway":"Graduates may enrol in further postgraduate qualification programmes such as the following:  \n\r\nMaster of Creative Practice (Ara).","developedBy":"Ara Institute of Canterbury","qualityAssuredBy":"New Zealand Qualifications Authority","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=4102"},"4140":{"i":"4140","entryRequirements":"Academic Requirements A Bachelor Honours Degree or a Postgraduate Diploma or an undergraduate degree followed by relevant professional experience. Alternative Requirements Applicants unable to evidence that they meet Academic Entry requirements, but who can demonstrate relevant skills and knowledge acquired through appropriate work or professional experience, may be approved for alternative entry. English Requirements If English is not the applicant's first language, applicants will need to provide a result from a test or qualification on the acceptable alternatives English Proficiency Outcomes Chart. Applicants who do not have evidence of English language skills and are a New Zealand citizen or permanent resident, may contact Ara for an assessment. IELTS 6.5 Academic (no lower than 6.0 in any subtest). Note: IELTS scores used must be taken from a single IELTS Test Report Form and are valid for two years from the date of the test. Applicants who have achieved NCEA Level 3 University Entrance requirements are not required to provide evidence of English language skills.","strategicPurposeStatement":"The Master of Creative Practice aims to enable ākonga to extend their domain of creative practice through enacting  \n\r\nan advanced, sustained and sophisticated body of independent practice-based research, which conforms to  \n\r\ninternationally recognised conventions.","graduateProfile":"1. Communicate a thorough account and critique of the relevant knowledge, principles, research methods and problem-solving techniques applicable to a specific domain of creative practice.  2. Demonstrate intellectual independence, critical thinking, analytic rigour and self-directed learning in the design and execution of a self-directed creative project.  3. Apply domain-based knowledge to practice-based research; analyse and develop arguments from primary evidence.  4. Demonstrate knowledge of a range of research perspectives, including engagement with Te Ao Māori to support creative practice. 5. Demonstrate mastery and work independently to undertake sustained and substantial, practice-based research in a specific domain","educationPathway":"Graduates may enrol in further postgraduate qualification programmes such as the following:  \n\r\nPhD  \n\r\nDMus/DPhil/DocFA  \n\r\nTeacher Education qualifications","developedBy":"Ara Institute of Canterbury","qualityAssuredBy":"New Zealand Qualifications Authority","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=4140"},"4460":{"i":"4460","entryRequirements":"The academic entry requirement for the THkT Poutiritāeo is one of the following:\n\r\n·\tan NZQF-listed Bachelor's or higher level degree (or equivalent) in a creative practice field with a minimum of the equivalent to a B- (B Minus) average across the final year of study as per the EIT-specified 11-point achievement-based grading system;\n\r\nor\n\r\n·\tin the absence of the above, provisional admission on the basis of an evaluation of a portfolio of work;\n\r\nor\n\r\n·\tat the Dean's discretion, where an applicant's situation is compelling but not covered by the requirements listed above.","strategicPurposeStatement":"MPCP (Poutiritāeo) provides the opportunity to apply an advanced body of knowledge, derived from research to a body of publicly accessible creative work. This sustained body of creative work will develop, extend and refine prior professional practice, processes and knowledge.MPCP (Poutiritāeo) shall be characterised by advanced study in creative practice, and as such, the programme shall:*Require  intensive  and  advanced  study,  building  on  a  foundation  of  undergraduate  knowledge  and skills;*Require a sustained high degree of self-directed and independent work;*Extend understanding of the application of research to a sustained creative practice discipline;*Require  excellent  communication  skills  for  critically  analysing,  synthesising,  evaluating,  and  influencing issues relevant to sustained creative practice;*Expect  graduates  to  demonstrate  skills  of  research,  critical  analysis,  constructive  synthesis  and  application  so  as  to  demonstrate  scholarly  inquiry,  independence  of  thought,  and  sustained advanced practice.","graduateProfile":"Graduates of this programme will be able to: Contextualise their practice and generate new understandings in relation to relevant communities, contemporary concepts, models, theory, technologies and professional practice management techniques.  \n\r\nResearch and critically analyse the relevant concepts, theories and philosophy to create a sustained body of highly specialised knowledge that is then applied in an advanced effective creative project. The project will identify and contextualise the relevant conceptual, theoretical and philosophical stances for effective creative professional practice.  \n\r\nProduce a sustained and advanced body of creative work to significant exhibition/production standard that demonstrates mastery that develops, extends and refines prior professional practices, processes and knowledge.","educationPathway":"Painter, sculptor, printmaker, designer, Ta Moko artists, curators, multi-media artist or other creative practice fields.","developedBy":"Eastern Institute of Technology","qualityAssuredBy":"New Zealand Qualifications Authority","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=4460"},"AU5700":{"i":"AU5700","entryRequirements":"Completed the requirements for a Bachelors degree with a minimum GPA or relevant professional experience.","strategicPurposeStatement":"PGCertFA graduates  will have integrated knowledge and experience of the studio, technological and theoretical aspects of a contemporary artistic practice medium to an advanced standard. They will be able to build a self-directed portfolio, and maintain a high level of flexible employability while responding to the needs of industry,  society and their own capacity for expression.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5700"},"AK3483":{"i":"AK3483","entryRequirements":"A relevant bachelor's degree completed to a merit standard. Applicants may be required to submit a portfolio of work and/or attend a selection interview.","strategicPurposeStatement":"MA&D graduates will have advanced knowledge and understanding in their chosen field. They will be critical and reflective, with strong applied research capability in a creative art and design context. They will have demonstrated the ability to engage in a sustained period of research, and may progress to further study at doctoral level.","developedBy":"Auckland University of Technology","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AK3483"},"MY0402":{"i":"MY0402","entryRequirements":"A relevant bachelor's degree.","strategicPurposeStatement":"Graduates will have advanced knowledge and skills in the theory and practice of Maori visual arts.","developedBy":"Massey University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=MY0402"},"VI001W":{"i":"VI001W","entryRequirements":"A Victoria University of Wellington bachelors degree (or graduate diploma) in design, or equivalent from another university; or demonstrated ability or professional experience","strategicPurposeStatement":"-","graduateProfile":"Graduates will have enhanced their existing design skills, or extended their skills into a new area, in areas such as industrial design, product design, additive manufacturing, game design, visual effects and post-production, and interaction design. They will be prepared for further postgraduate study in a design discipline. Some graduates will be able to progress to the Postgraduate Diploma in Design Innovation [PGDipDI, VI00Y6] or the Master of Design Innovation [MDI, VI00Y5].","educationPathway":"-","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI001W"},"OT5070":{"i":"OT5070","entryRequirements":"Minimum entry requirements are:  \n\r\n1. A postgraduate visual arts qualification with a minimum of 60 credits at level 8 and with an overall grade of B (70%) or higher.  \n\r\n2. Exceptional applicants not meeting the entry requirements but with appropriate documented professional experience may be referred to the Centre for Assessment of Prior Learning (CAPABLE).  \n\r\n3. International students must demonstrate that they have equivalent experience / qualifications as home students and for those whose first language is not English, must show evidence of English Language competence at IELTS overall band score of 6.5 with no individual band less than 6.0 or equivalent.","strategicPurposeStatement":"The Master of Visual Arts programme aims to provide students with the opportunity to demonstrate mastery of the professional, conceptual and technical skills relevant to their chosen field in the production of an independently developed and original exhibition and written text.","graduateProfile":"Students from this programme will graduate with a postgraduate qualification aligned to international initiatives concerning benchmarking and which have parity with similar programmes in the national and international arena. They will  \n\r\n· have demonstrated mastery in the production of a body of studio work exhibited publicly and benchmarked nationally and internationally  \n\r\n· have demonstrated mastery in the production of an extended essay which connects their studio work with conceptual ideas and with the work of their community of profession as based on their participatory engagement with a series of seminars on contemporary practice theory  \n\r\n· have demonstrated mastery in the delivery of an oral seminar on their own studio work in relation to contemporary visual arts practices  \n\r\n· have demonstrated mastery in the articulation of the integration of their own making and writing in the public presentation of this material  \n\r\n· have a sense of achievement and confidence as practitioners  \n\r\n· have highly developed skills in their chosen field that distinguish them as pragmatic, resourceful, adaptable and flexible  \n\r\n· have an applied understanding of the historical and contemporary conventions of their field  \n\r\n· have identified their own (continuing) learning needs and possess the research skills and motivation necessary to locate and acquire new skills, knowledge and understanding \n\r\n have demonstrated through explicit articulation within the programme an awareness of biculturalism and its relevance to both the wider field of the visual arts and its relevance to their own studio project  \n\r\n· have demonstrated through an explicit articulation within the programme an awareness of initiatives that ensure sustainability in their chosen field through the informed use of resources and through an understanding of the ways in which the practice of art contributes to the sustainability of cultures and the socio-economic framework of the wider world  \n\r\n· have articulated within the programme an understanding of their own skills and field of practice and their relationship to the wider world, with a sensitivity to both specialist and general audiences  \n\r\n· have demonstrated within the programme the ability to be able to critically and with intellectual rigour appraise art practices  \n\r\n· have demonstrated a mastery of professional practices that enable them to be productive in the development of their own careers and to initiate, develop and complete projects  \n\r\n· be visionary, capable of taking risks, lateral thinkers, effective problem solvers and adaptable to a range of professional challenges  \n\r\n· be effective team workers demonstrating trust and good communication and networking skills towards the completion of a body of studio work.","educationPathway":"Graduates may pathway into the Otago Polytechnic Master of Fine Arts.","developedBy":"Otago Polytechnic","qualityAssuredBy":"New Zealand Qualifications Authority","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=OT5070"},"AU5592":{"i":"AU5592","entryRequirements":"This is an exit qualification. Students need to have been enrolled in the MDMT, passed at least 30 points in that degree, and been recommended for admission by the Academic head or nominee.","strategicPurposeStatement":"Graduates of the PGDipThDance will understand foundational principles of dance as a therapeutic practice as it pertains to individuals, communities and specific stakeholders. They will be informed, responsive practitioners with insight into appropriate practices for facilitating therapeutic dance in a range of settings","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5592"},"WK2422":{"i":"WK2422","entryRequirements":"12 credits NCEA Level 1 in English or a pass in School Certificate English, or other equivalent qualification.  .    Internationals IELTS Score of 6.0 in all bands.","strategicPurposeStatement":"Graduates will have acquired advanced knowledge and skills in a specialised area of Media Arts through completion of a sustained research project.  Specialisations include graphic design, digital media design, painting, moving image, sculpture, photography, music and communication","developedBy":"Waikato Institute of Technology","qualityAssuredBy":"Quality Assurance Division, NZQA","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=WK2422"},"OO0483":{"i":"OO0483","entryRequirements":"A bachelor's degree in a relevant field, or equivalent.","strategicPurposeStatement":"Graduates of this degree programme will have attained a high level of professional mastery, craft and practical skill in a field of specialisation (e.g. acting, direction, design, or scriptwriting).","developedBy":"University of Otago","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=OO0483"},"MY0336":{"i":"MY0336","entryRequirements":". Admission to the Degree of Master of Screen Arts requires that the candidate will:  (a) meet the University admission requirements as specified;  and will:  (b) have been awarded or qualified for a relevant Bachelor's degree or equivalent qualification with a grade average of at least B; or  (c) have been awarded or qualified for the Bachelor of Screen Arts (Honours) with a grade average of at least B across the 700-800 level courses, or equivalent; or  (d) have been awarded or qualified for the Postgraduate Diploma in Screen Arts with a grade average of at least B, or equivalent; or  (e) have been granted admission under the Admission with Equivalent Status regulations and demonstrate practical, professional and scholarly experience at an appropriate level;  and will have:  (f) been selected into the programme on the basis of an interview and assessment of a portfolio of relevant work prepared by the candidate.","strategicPurposeStatement":"Master of Screen Arts graduates will make a contribution to knowledge in their field; demonstrate an advanced command of research methods as they relate to their specialism and implement the findings of research through original creative practice and exegetical component.","graduateProfile":"3 papers, internal assessment and examinations; thesis, internal and external examiner; exhibition/presentation of creative practice and exegetical component, plus oral examination.","developedBy":"Massey University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=MY0336"},"CN0908":{"i":"CN0908","entryRequirements":"Applicants must have a Bachelor's degree in Music with first or second class honours, or more usually a Master's degree in Muisc with distinction or merit or equivalent and a successful audition.","strategicPurposeStatement":"Doctor of Musical Arts graduates will have the ability to compose or perform musical works at the highest professional level. Graduates will be performers or composers of an international standard, equipped with a thorough knowledge of artistic practice in their discipline, intellectual independent thinking and expertise in current research methodologies in their field.","developedBy":"University of Canterbury","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=CN0908"},"AU4070":{"i":"AU4070","entryRequirements":"Master of Fine Arts with First Class or Second Class (Division 1) Honours or an approved equivalent qualification","strategicPurposeStatement":"DocFA graduates will be highly skilled practitioners able to contribute at an internationally recognised standard in their chosen field of Fine Arts and to exercise analytical and critical judgment of their own and others' work.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU4070"},"WI0146":{"i":"WI0146","entryRequirements":"Bachelor of Computer Graphic Design or equivalent qualification.","strategicPurposeStatement":"Graduates will understand the roles and responsibilities of a professional designer, and be able to apply knowledge and research skills and attitudes learned through problem solving projects in selected areas of computer graphic design. They will have a deep understanding of aspects of computer graphic design, an understanding of the role and context of research in computer graphic design, and the ability to keep abreast of new developments in technology.","developedBy":"University of Waikato","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=WI0146"},"MY0183":{"i":"MY0183","entryRequirements":"Admission to the Postgraduate Diploma in Screen Arts requires that the candidate will: (a) meet the University admission requirements as specified; and (b) have been awarded or qualified for the award of a Bachelor of Screen Arts or equivalent; and (c) have been selected into the programme on the basis of a portfolio prepared by the candidate, and an interview if required.","strategicPurposeStatement":"The Postgraduate Diploma in Screen Arts graduates will demonstrate attributes of Creativity - Toi, Virtuosity - Mohio, Understanding - Matauranga and Connectedness - Whanaungatanga and will be able to: * Display an ability to engage with the richness and variety of different views within the screen sector, acknowledging their contribution to the cultural identity of Aotearoa New Zealand.  * Demonstrate a broad, critical understanding of the discourse, professional practices and production processes and their multiple global contexts.  * Demonstrate understanding of the relationship between production and audiences, clients, markets, users, consumers, participants and citizens.  * Be intellectually curious and adaptable, willing to embrace new ideas and accommodate risk and uncertainty. * Have clear goals for the continuation of intellectual and/or professional development.  * Apply exploratory and transformative thinking to generate ideas, proposals, creative works and arguments in response to project demands. * Critically reflect on and evaluate their own work and the work of other practitioners and scholars.  * Initiate and contribute to innovative developments in the screen sector through creative practice based research.  Demonstrate critically informed competency in the management and operation of production technologies, procedures and processes.  * Combine technical excellence with intellectual and conceptual rigour in order to advance creative processes in all forms of production.  * Skilfully utilise analytical, evaluative and synthesising iterative processes in order to transform ideas into production outcomes.","graduateProfile":"120 credits of a variety of internal assessments, tests and projects.","developedBy":"Massey University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=MY0183"},"MY0733":{"i":"MY0733","entryRequirements":"Bachelor of Fine Arts or equivalent and relevant background and experience.","strategicPurposeStatement":"Postgraduate Diploma in Fine Arts graduates will be able to identify and critically analyse the broader historical and theoretical dialogue that relates to their chosen area(s) of fine arts practice; demonstrate a strong ability to manipulate their chosen materials in fine arts; and apply appropriate research techniques and studio practices in the search for new directions in fine arts.","developedBy":"Massey University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=MY0733"},"AK1245":{"i":"AK1245","entryRequirements":"Completion of a relevant master's degree or a bachelor's degree with honours with at least first or second class (first division) honours, or equivalent; advanced training in research and five years' professional experience in the area of study.","strategicPurposeStatement":"DDes graduates will be experienced business, marketing and creative industry professionals with an advanced level of research, scholarship and practice in design and business innovation. They will be reflective practitioners with integrated insights and approaches to creating valuable, innovative and competitive products, systems and services.","developedBy":"Auckland University of Technology","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AK1245"},"AK1094":{"i":"AK1094","entryRequirements":"Bachelor's degree or equivalent,","strategicPurposeStatement":"PgCertCIT graduates will be able to respond to change, use new technologies, and turn creative ideas into real projects. They will think carefully about the social, cultural (including Maori and Indigenous), environmental, and political impact of their work. Graduates may continue studying or take on leadership roles in creative and technology-related fields.","graduateProfile":"Case analyses, digital portfolios, reflective journals, and scenario responses","developedBy":"Auckland University of Technology","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AK1094"},"OO0418":{"i":"OO0418","entryRequirements":"A 4 year Bachelors degree; or a 3 year Bachelors degree and 3 years relevant experience; or equivalent","strategicPurposeStatement":"This masters degree provides the theoretical and practical exploration of dance as well as exploring its diversity within social, educational, artistic and cultural contexts.","developedBy":"University of Otago","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=OO0418"},"VI003V":{"i":"VI003V","entryRequirements":"A bachelor's degree in a relevant subject, with a B grade average or better, and evidence of proficiency in at least one language other than English to the equivalent of at least 40 300-level points, with a B grade average or better. Examples of relevant subjects include a language other than English and intercultural communication studies.","strategicPurposeStatement":"Graduates will acquire the theoretical and practical set of skills necessary to be cross-culturally competent as well as opportunities and platforms to apply them through the most powerful form of intercultural communication: translation. These skills are in high demand among employers across a wide range of areas, including business (international trade, advertising, website localisation, hospitality and tourism), education (second language learning, multicultural instruction, international relations, development studies, digital humanities, medical humanities, literature and linguistics), and the creative industries (film production, subtitling and dubbing, graphic design, creative writing, advertising). Graduates will be able to successfully acquire, analyse, interpret, negotiate and reproduce information and data across linguistic, cultural, and socio-political contexts. As well as being well-prepared for employment in the above fields, some graduates may be able to continue to doctoral study in Translation Studies.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI003V"},"CN0177":{"i":"CN0177","entryRequirements":"An approved Bachelor's degree.","strategicPurposeStatement":"Graduates will: understand the role and effects of strategic communication within society; understand major theories in strategic communication and communication management;  identify and produce strategies for effective communication within organisations and for targeted audiences, using a range of media; adapt their skills and knowledge to a networked, interactive and fluid digital communication environment; understand communication in its many intercultural, globalising and postcolonial contexts, particularly the bicultural context of Aotearoa New Zealand; reflect critically and ethically on communication plans and strategies; understand and apply methodologies of formative and evaluative research for strategic communication; have an in-depth knowledge of the management of communication in Aotearoa New Zealand and globally.","developedBy":"University of Canterbury","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=CN0177"},"VI003X":{"i":"VI003X","entryRequirements":"A bachelor's degree in a relevant subject, with a B grade average or better, and evidence of proficiency in at least one language other than English to the equivalent of at least 40 300-level points, with a B grade average or better. Examples of relevant subjects include a language other than English and intercultural communication studies.","strategicPurposeStatement":"Graduates will acquire the theoretical and practical set of skills necessary to be cross-culturally competent as well as opportunities and platforms to apply them through the most powerful form of intercultural communication: translation. These skills are in high demand among employers across a wide range of areas, including business (international trade, advertising, website localisation, hospitality and tourism), education (second language learning, multicultural instruction, international relations, development studies, digital humanities, medical humanities, literature and linguistics), and the creative industries (film production, subtitling and dubbing, graphic design, creative writing, advertising). Graduates will be able to successfully acquire, analyse, interpret, negotiate and reproduce information and data across linguistic, cultural, and socio-political contexts.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI003X"},"AK1322":{"i":"AK1322","entryRequirements":"A relevant bachelors degree.","strategicPurposeStatement":"PgCertCS graduates wiill have advanced knowledge and understanding of communication theory and its application to current professional practices. They will be able to engage analytically, critically and reflectively within their chosen field. They may progress to further study at postgraduate diploma or masters level.","developedBy":"Auckland University of Technology","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AK1322"},"AU5754":{"i":"AU5754","entryRequirements":"Must be admitted to and passed at least 30 points in the Master of Communication, and been recommended for admission by the Dean or nominee.","strategicPurposeStatement":"PGDipC graduates will develop competencies that are highly valued across a broad range of employment sectors. Graduates will be well-prepared for roles in communication professions, including media, public relations and advertising. Students will also be well-placed to take on roles across a wide range of public, private and social organisations in which advanced communication skills are highly sought-after, including government agencies; community and charitable organisations; for-profit and not-for-profit enterprises; and civil society organisations.","graduateProfile":"Assessment methods include coursework assignments, projects and exams.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5754"},"MY0013":{"i":"MY0013","entryRequirements":"A New Zealand University Entrance Qualification or equivalent plus a portfolio of work and an interview.","strategicPurposeStatement":"Graduates will demonstrate versatility and competence across a range of contemporary art practices, and be able to make critically informed choices towards a future as a practitioner or arts professional. They will have strengths in critical studies and contemporary arts, and be capable of demonstrating an understanding of cultural heritage, difference and diversity in contemporary art practices. They will apply appropriate research methodologies towards an understanding of new knowledge in contemporary art.","developedBy":"Massey University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=MY0013"},"CN0187":{"i":"CN0187","entryRequirements":"An approved Bachelor's degree.","strategicPurposeStatement":"Graduates will able to apply advanced skills in writing to a range of professional, technical, organisational, community, and creative contexts. They will be able to write effectively within a range of registers and genres, and for a range of purposes; to respond to the requirements of different audiences and media; to engage the creative dimensions of professional writing and the professional dimensions of creative writing; to undertake research relevant to their writing tasks; to analyse critically the writing of others and apply what they discover to their own writing; and to provide advanced editorial advice for other writers.","developedBy":"University of Canterbury","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=CN0187"},"AK1298":{"i":"AK1298","entryRequirements":"Bachelors degree, portfolio of artwork, research proposal","strategicPurposeStatement":"Graduates will have the research and critical thinking skills to prepare them for further postgraduate study in the field of Art and Design","developedBy":"Auckland University of Technology","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AK1298"},"AK1323":{"i":"AK1323","entryRequirements":"A relevant bachelors degree completed to a merit standard.","strategicPurposeStatement":"MCS graduates will have advanced knowledge and understanding of communication theory and its application to current professional practices. They will be able to engage analytically, critically and reflectively within their chosen field and will have demonstrated an ability to undertake a sustained period of research and have presented the results by way of a thesis. They will be prepared for study at doctoral level.","developedBy":"Auckland University of Technology","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AK1323"},"OT4798":{"i":"OT4798","entryRequirements":"You must hold a recognised bachelor's degree in fine arts OR an equivalent four year programme with at least a B grade average. Three year undergraduate degrees may be considered but you must have achieved an A pass average in the major subject. \n\r\nYou must submit an annotated portfolio, curriculum vitae and a research proposal, including an annotated bibliography. The portfolio must be no larger than 15MB. \n\r\nSelection for admission includes an interview. \n\r\nIf you do not hold the above qualifications, you must demonstrate appropriate ability through a current portfolio and a related project proposal which will be approved by the Master of Fine Arts Admissions Committee. \n\r\nInternational students will be individually assessed to ensure they meet the entry requirements. \n\r\nIf English is not your first language, you must also demonstrate English language skills equivalent to an IELTS overall band score (academic) of 6.5, with no band score less than 6.0.","strategicPurposeStatement":"The Master of Fine Arts places emphasis on the integration of studio and theoretical components; on the manufacture of ideas in the process of working with the tools and materials of making and writing and requires a high standard of studio research and its contextualisation and critical analysis within an acadeic dissertation. Graduates will be able to: \n\r\n&#61607; Articulate and debate the aims, methods and outcomes of their research practices. \n\r\n&#61607; Make a significant and engaged contribution within the community of their profession in the visual arts. \n\r\n&#61607; Demonstrate the capacity for self-directed study and the ability to work independently. \n\r\n&#61607; Demonstrate evidence of advanced knowledge about a specialised area of theoretical and applied research relevant to the visual arts field. \n\r\n&#61607; Plan and carry out original research to internationally recognised standards, demonstrating a high order of skill, analytical ability and critical evaluation. \n\r\nArticulate and debate the links between research methods, theoretical enquiry, and studio based research in relation to their approved topic of study. \n\r\nFor more information refer Otago Polytechnic \nhere","educationPathway":"This qualification provides you with the necessary degree to pursue a Doctor of Visual Arts (DVA), a Doctor of Fine Arts (DocFA) and/or a Doctor of Philosophy (PhD) in New Zealand or overseas","developedBy":"Otago Polytechnic","qualityAssuredBy":"New Zealand Qualifications Authority","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=OT4798"},"MY0337":{"i":"MY0337","entryRequirements":"1. Admission to the Degree of Master of Commercial Music requires that the candidate will:  (a) meet the University admission requirements as specified;  and will:  (b) have been awarded or qualified for a relevant Bachelor's degree or equivalent qualification with a minimum grade average of at least B; or  (c) have been awarded or qualified for the Bachelor of Commercial Music (Honours) with a grade average of at least B across the 700-800 level courses, or equivalent; or  (d) have been granted admission under the Admission with Equivalent Status regulations and demonstrate practical, professional and scholarly experience at an appropriate level;  and will have:  (e) been selected into the programme on the basis of an interview and assessment of a portfolio of relevant work prepared by the candidate.","strategicPurposeStatement":"Master of Commercial Music graduates will make a contribution to knowledge in their field; demonstrate an advanced command of research methods as they relate to their specialism and implement the findings of research through original creative practice and exegetical component.","graduateProfile":"3 papers, internal assessment and examinations; thesis, internal and external examiner; exhibition/presentation of creative practice and exegetical component, plus oral examination.","developedBy":"Massey University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=MY0337"},"AU5155":{"i":"AU5155","entryRequirements":"Bachelor of Music or equivalent degree, or the attainment of a level of competence approved by Senate or its representative that is considered equivalent to a degree and appropriate for the programme to be undertaken.","strategicPurposeStatement":"PGDipMus graduates will have undertaken a year's study in specialist and ancillary courses that centre and deepen their musical understanding and their performance skills, and give them the positioning they need for research at Master's level.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5155"},"AU5666":{"i":"AU5666","entryRequirements":"Completed the requirements for a Bachelors degree with a minimum Grade Point Average (GPA); or a Bachelors degree and the Postgraduate Certificate in Design with a minimum GPA; Or have attained extensive relevant practical, professional or scholarly experience deemed equivalent and performed at an acceptable level in any tests of academic aptitude, portfolio and/or interviews prescribed by Senate or its representative.","strategicPurposeStatement":"MDes graduates will be proficient in a range of contemporary design methodologies and technologies, and be able to apply advanced design skills and practices to create new products, services and systems on behalf of industry, society and the economy. They will be creative, interdisciplinary, entrepreneurial practitioners able to pursue personal professional goals including progressing to doctoral studies.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5666"},"AK1261":{"i":"AK1261","entryRequirements":"A relevant bachelor's degree completed to a merit standard.","strategicPurposeStatement":"BCS (Hons) graduates will have significantly advanced applied and academic skills gained in their undergraduate degree and have developed the ability to undertake advanced independent research in a specialised field of communication studies. They will have the research and critical thinking skills to prepare them for the future. Graduates will also be prepared for further postgraduate study at master's or doctoral level.","developedBy":"Auckland University of Technology","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AK1261"},"AU5790":{"i":"AU5790","entryRequirements":"Being enrolled in the Master of Creative Arts Therapy, passed a minimum number of points, and have approval by the Programme Director.","strategicPurposeStatement":"Postgraduate Diploma in Therapeutic Arts graduates will know and understand the principles, concepts and ideas that define Creative Arts Therapy. They will be critical, reflective practitioners able to apply principles of therapeutic creative arts within their personal professional goals and in further postgraduate study.?","graduateProfile":"Assessment modes include: essays, portfolios, practical demonstrations, presentations.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5790"},"VI00M6":{"i":"VI00M6","entryRequirements":"Master's degree and a pass in an audition.","strategicPurposeStatement":"The Artist Diploma provides each student with the opportunity to focus intensively on performance, and in the process to develop the skills necessary for an emerging career as a concert artist.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI00M6"},"VI004F":{"i":"VI004F","entryRequirements":"A Bachelor's degree in a relevant subject with an average grade of B or better. Relevant subjects include communication, journalism, cultural studies, film, media studies, music, marketing, public relations, language and literary studies, and science.","strategicPurposeStatement":"Postgraduate Diploma in Communication graduates will have a strong understanding of the underpinning key principles of communication. They will be able to critically analyse communication processes from multiple perspectives in a range of different domains and work across different public and private sectors, particularly in communication-related industries and institutions. They will have the skills necessary to debate complex issues related to communication in a constructive and rational manner. Graduates will also be able to communicate this knowledge in multiple contexts, using a variety of methods (e.g., written, oral, audio-visual).  They will be well-prepared to take on leadership roles in communications and media-related industries and institutions. Students who complete the requirements of the PGDipC may be able to continue to the Master of Communication.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI004F"},"MY0051":{"i":"MY0051","entryRequirements":"Admission to the Bachelor of Commercial Music (Honours) requires that the candidate will:    (a) meet the University admission requirements as specified; and    (b) have been awarded or qualified for a Bachelor of Commercial Music,?having achieved at least a B grade average over the highest level courses, or equivalent.","strategicPurposeStatement":"The Bachelor of Commercial Music (Honours)?aims to provide an advanced?professional education in a research-led programme of study that equips graduates to operate in a range of roles with awareness of current music industry models and transferable skills that are essential in the highly competitive music industry with these five defining attributes:? Creativity - Toi;?Virtuosity - Mohio;?Understanding - Matauranga;?Autonomy -?Mana;?Connectedness - Whanaungatanga.    Through both specialist and transferable knowledge and skills, the Bachelor of Commercial Music (Honours) degree will enable graduates to make?wide-ranging cultural, social and economic contributions to society.","developedBy":"Massey University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=MY0051"},"OO0363":{"i":"OO0363","entryRequirements":"Bachelor of Science or alternative qualifications","strategicPurposeStatement":"This programme provides an internationally recognised qualification in Natural History Filmmaking and Communication.","developedBy":"University of Otago","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=OO0363"},"AU0404":{"i":"AU0404","entryRequirements":"Completed the requirements for a  Bachelor of Music or Bachelor of music (Honours) or Postgraduate Diploma in Music, and a minimum Grade Point Average (GPA), or an approved equivalent qualification or a Bachelor of Music and the PGCertMus with a minimum GPA.","strategicPurposeStatement":"MMus graduates will be skilled practitioners in their chosen field of musical study able to demonstrate a high level of practical and theoretical competence and understanding.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU0404"},"OO0009":{"i":"OO0009","entryRequirements":"A candidate must normally be a graduate of the University of Otago, with a Bachelor of Music degree conferred at least five years before candidature.","strategicPurposeStatement":"Graduates will have demonstrated special excellence in original musical composition.","developedBy":"University of Otago","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=OO0009"},"OT5067":{"i":"OT5067","entryRequirements":"Applicants must have successfully completed the three years of the Bachelor of Visual Arts offered by Otago Polytechnic or any equivalent qualification at Bachelor?s level or above with a B (70%) or higher pass in all areas of study undertaken in the final year. \n\r\nNormal commencement of Honours study must occur within five years of the successful completion of the degree.  Exceptions will require the approval of the postgraduate coordinator based on advice from the relevant head of department and the supervisor. \n\r\nInternational students must demonstrate that they have equivalent experience/qualifications as domestic students and those, whose first language is not English, must provide evidence of English language competence at IELTS level 6.5 (in all areas of the test).","strategicPurposeStatement":"Graduands will be confident and flexible visual arts practitioners in their chosen studio areas, who can integrate their material and conceptual knowledge in transferable ways within their practices and for the benefit of the employment sector.  They are lifelong learners who are productive, lateral thinkers, effective problem solvers in the wider national and international arena.  Graduands are able to produce a coherent body of studio work and can relate this work to its conceptual underpinnings and its wider community of practice in the field of contemporary art.","developedBy":"Otago Polytechnic","qualityAssuredBy":"Quality Assurance Division, NZQA","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=OT5067"},"OO0508":{"i":"OO0508","entryRequirements":"A bachelor's degree or equivalent.","strategicPurposeStatement":"Holders of this certificate will have a high-level understanding of science communication theory, will have the ability to think like professional science communicators, and will have created communication resources to add to their portfolio.","graduateProfile":"Not applicable","educationPathway":"Not applicable","developedBy":"University of Otago","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=OO0508"},"AU5516":{"i":"AU5516","entryRequirements":"A relevant Bachelors degree with a minimum Grade Point Average (GPA).  .","strategicPurposeStatement":"Graduates of the Bachelor of Dance Studies (Honours) programme will know and understand the principles, concepts and ideas that define dance theory and practice in relation to dance making, pedagogy and research. They will be critical, reflective practitioners able to pursue personal professional goals and postgraduate study.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5516"},"AU4045":{"i":"AU4045","entryRequirements":"Completed the requirements for a Bachelors degree with a minimum Grade Point Average (GPA) or  at least three years of relevant professional experience","strategicPurposeStatement":"PGDipFA graduates will be informed practitioners in the Fine Arts demonstrating an advanced individual interest, knowledge and creative practice in a chosen area of study.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU4045"},"WI0867":{"i":"WI0867","entryRequirements":"Master of Music with First or Second Class Honours or equivalent and audition successfully.","strategicPurposeStatement":"A DMA graduate will be an outstanding performing musician equipped for a career as a professional soloist, ensemble member, or teacher. DMA graduates are ideally qualified for careers in the tertiary sector as performer-academics. A graduates musical performances will be of an international level of quality, enriched and informed by applied advanced research into his or her speciality, and revealing an awareness of current scholarly work in the field.","developedBy":"University of Waikato","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=WI0867"},"MY0053":{"i":"MY0053","entryRequirements":"Admission to the Bachelor of Screen Arts with Honours requires that the candidate will meet the University admission requirements as specified.","strategicPurposeStatement":"The Bachelor of Screen Arts with Honours aims to provide high-level professional education in its programme of study that equips graduates to operate in a range of roles in screen production industries with these five defining attributes:  Creativity - Toi; Virtuosity - Mohio; Understanding - Matauranga; Autonomy - Mana; Connectedness - Whanaungatanga. This four-year qualification equips students with advanced technical skills across a range of disciplines, alongside focused and specialised teaching in research methods pertinent to the development of creative practice and skills in independent critical reflection and analysis.","graduateProfile":"Admission to the Bachelor of Screen Arts with Honours requires that the candidate will meet the University admission requirements as specified.","developedBy":"Massey University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=MY0053"},"VI002Z":{"i":"VI002Z","entryRequirements":"A Victoria University of Wellington Bachelor of Design Innovation in media design, or equivalent qualification, with an average grade of B or better.","strategicPurposeStatement":"Graduates will have the technical knowledge and skills to develop practical design solutions for visual effects (VFX). Their comprehensive knowledge of design processes will allow them to formulate and develop creative design strategies and to independently research, master and integrate new design technologies and tools. They will demonstrate teamwork and written and oral communication skills.  They will have the professional and enterprise skills necessary for working effectively in creative VFX-related ICT organisations, in areas such as game design, virtual reality design, animation and film production and post-production. Graduates may also be able to progress to a research-based master's or higher degree","graduateProfile":"NA","educationPathway":"NA","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI002Z"},"AU4016":{"i":"AU4016","entryRequirements":"MMus from the University of Auckland","strategicPurposeStatement":"Graduates will have a highly developed knowledge and understanding of a wide range of musical styles and techniques, and advanced skills in composition.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU4016"},"VI00W9":{"i":"VI00W9","entryRequirements":"Bachelor of Music and either passed an audition (Performance), or submitted an acceptable portfolio of compositions (Composition), or sound-based works (Sonic Arts).","strategicPurposeStatement":"Holders of the Postgraduate Diploma in Music will have a high level of artistic accomplishment in musical performance or sound-based creativity. Performers will have a high degree of confidence to apply for auditions and competitions, and will have the ability to apply skills and attributes essential to a professional performing career in music. Composers and sonic artists will have a high standard of work presentation, and a high degree of individuality and originality.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI00W9"},"MY0426":{"i":"MY0426","entryRequirements":"Bachelor of Fine Arts or equivalent, and a portfolio of work.","strategicPurposeStatement":"Master of Fine Arts graduates will make a contribution to new knowledge in fine arts; demonstrate a command of research methods as they relate to fine arts and implement the findings of research in fine arts.","developedBy":"Massey University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=MY0426"},"MY0222":{"i":"MY0222","entryRequirements":"A relevant bachelor's degree.","strategicPurposeStatement":"Holders will have advanced knowledge and skills in the theory and practice of Maori visual arts.","developedBy":"Massey University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=MY0222"},"AU5667":{"i":"AU5667","entryRequirements":"Completed the requirements for a Bachelors degree with a minimum Grade Point Average (GPA) or have attained extensive relevant practical, professional or scholarly experience deemed equivalent and performed at an acceptable level in any tests of academic aptitude, portfolio and/or interviews prescribed by Senate or its representative.","strategicPurposeStatement":"PGCertDes graduates will be proficient in the use of a range of contemporary design methodologies and technologies, and be able to apply design skills and practices to create new products, services and systems on behalf of industry, society and the economy.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5667"},"WI0572":{"i":"WI0572","entryRequirements":"A Bachelor of Design or equivalent qualification or demonstrated evidence of ability and adequate training for entry.","strategicPurposeStatement":"Graduates will have an advanced knowledge in a specialist area of design.","graduateProfile":"Graduates will have an advanced knowledge in a specialist area of design.","developedBy":"University of Waikato","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=WI0572"},"VI0011":{"i":"VI0011","entryRequirements":"Bachelor of Music or a Bachelor of Arts degree with music as the major subject.","strategicPurposeStatement":"A year of intensive study in a particular branch of music following the acquisition of a Bachelor of Music degree or a Bachelor of Arts degree with music as the major subject.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI0011"},"WK2525":{"i":"WK2525","entryRequirements":"Corresponding Bachelor with Honours or Postgrad Dip with minimum B grade average or appropriate equivalent practical, professional or educational experience as artist, designer or musician. Must present research project synopsis. May need pre-requisite Research Methodology. Internationals IELTS Score 6.5 with a minimum score of 6.0 in the written band.","strategicPurposeStatement":"The Master of Arts consists of a major body of research in studio-based practice in fields of Contemporary Visual Art, Design or Music or Communication.","graduateProfile":"Graduates will be able to articulate, analyse, compare and defend the positions and values of their field of practice and be able to extrapolate principles from this enquiry and apply them to the development of new outcomes.  Develop a body of work in Art, Design, Music or Communication that is a synthesis of personally invested creative predisposition, established and new methodological parameters, normal contextual constructs and theoretical account.","educationPathway":"Builds on wither the Bachelor of Media Arts (Honours) or equivalent.  Graduates can progress to doctoral study.","developedBy":"Waikato Institute of Technology","qualityAssuredBy":"Quality Assurance Division, NZQA","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=WK2525"},"AK1313":{"i":"AK1313","entryRequirements":"A relevant bachelor's degree or equivalent.","strategicPurposeStatement":"PgDipPMA graduates will have the research and critical thinking skills necessary to undertake further postgraduate study in the field of Performance and Media Arts. They will also be highly skilled, technically competent and innovative creative practitioners with the expertise to contribute to, as well as respond to, the rapidly changing performing arts, media arts, and creative industries.","developedBy":"Auckland University of Technology","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AK1313"},"CN0746":{"i":"CN0746","entryRequirements":"An approved Bachelor's degree or equivalent.","strategicPurposeStatement":"Graduates of the Master of Illustration will possess advanced creative, technical, professional and research capabilities across a range of illustrative practices. They will have developed a distinct authorial voice and demonstrated the ability to communicate complex ideas and narratives through diverse visual media. Graduates will possess advanced research skills in illustration, including the ability to design and conduct independent research projects. Through engagement with theory, history, and contemporary practice, they will critically situate their work within broader social, cultural, and ethical contexts. Equipped with business acumen and experience in both professional and research settings, graduates will be prepared to contribute meaningfully to the global illustration industry and critical research practice. Graduates will be industry-ready, with the ability to respond to client briefs, collaborate with diverse stakeholders, and sustain a professional practice within commercial, editorial, publishing, entertainment, design and other research environments.","graduateProfile":"A range of assessments will be used including written assignments, presentations, case studies and portfolios.","developedBy":"University of Canterbury","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=CN0746"},"VI00Y6":{"i":"VI00Y6","entryRequirements":"A Victoria University of Wellington bachelors degree (or graduate diploma) in design, or equivalent from another university; or demonstrated ability or professional experience.","strategicPurposeStatement":"The Postgraduate Diploma in Design Innovation programme will provide students with the advanced skills and knowledge necessary to gain professional employment and/or initiate projects in the fields of design Culture+Context, Interaction Design and Industrial Design.","graduateProfile":"Graduates will have enhanced their existing design skills and employability, or broadened their skills, in areas such as industrial design, product design, additive manufacturing, game design, visual effects and post-production, interaction design, UI/UX design, usability, exhibition design, service design and advertising. The PGDipDI may be awarded with a specialisation in computer graphics, culture+context, industrial design or media design. Graduates will be able to undertake directed research and will be well prepared for further postgraduate study in a design discipline. Some graduates will be able to progress to the Master of Design Innovation (VI00Y5)","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI00Y6"},"WI0951":{"i":"WI0951","entryRequirements":"Bachelors degree or equivalent","strategicPurposeStatement":"Bachelor of Design with Honours (BDes(Hons)) graduates will have advanced professional knowledge and an introduction to the research literature in a subject area represented in a major in an undergraduate design degree. They will be equipped with the capabilities to conduct independent research. Higher performing graduates will be prepared to enter postgraduate studies leading to higher-level qualification such as a masters degree or PhD.","developedBy":"University of Waikato","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=WI0951"},"WI256":{"i":"WI256","entryRequirements":"Bachelor of Design degree or equivalent with the required grade average. Those students who have an honours degree in a relevant field, may take 120 credits to complete the MDes.","strategicPurposeStatement":"Graduates will have a detailed and advanced knowledge of aspects of their chosen area of specialisation.","graduateProfile":"N/A","educationPathway":"N/A","developedBy":"University of Waikato","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=WI256"},"OO0563":{"i":"OO0563","entryRequirements":"Bachelor of Music or appropriate alternative qualification or experience.","strategicPurposeStatement":"Graduates of this programme will acquire a comprehensive understanding and mastery of industry-standard knowledge and skills.","graduateProfile":"Internal assessment, examinations, creative project, dissertation.","developedBy":"University of Otago","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=OO0563"},"VI00R2":{"i":"VI00R2","entryRequirements":"A relevant Bachelor's degree or equivalent, including some study of psychology, plus an audition and interview.","strategicPurposeStatement":"Graduates of this programme will demonstrate knowledge, skills and understanding of principles and practices defining the field of music therapy. Graduates will be critical reflective practitioners able to pursue professional goals and contribute to research.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI00R2"},"MY0175":{"i":"MY0175","entryRequirements":"Bachelor of Design, Bachelor of Fine Arts, Bachelor of Creative Media Production, Bachelor of Commercial Music, Bachelor of M?ori Visual Arts, or equivalent.","strategicPurposeStatement":"Graduates of the Postgraduate Certificate of Creative Arts will be able to:  A. Knowledge and understanding  Evaluate research methods to determine their potential application to a creative research project (Matauranga)  B. Values and Attitudes  Be intellectually curious and adaptable, willing to embrace new ideas and accommodate risk and uncertainty (Toi)  C. Skills (Cognitive and Intellectual)  Apply exploratory thinking to generate creative research proposals (Toi)  D. Skills (Subject Specific/ Professional)  Utilise analytical, evaluative and synthesising iterative processes in order to transform ideas into material outcomes (Mohio)  E. Skills (Transferable)  * Demonstrate effective visual, oral, sonic and written communication skills (Whanaungatanga)  * Interact effectively, ethically and professionally with others (Whanaungatanga)  * Think and work independently, making autonomous decisions, managing workload and deadlines (Mana)  * Source and astutely utilise information in a variety of forms and contexts (Matauranga)  A candidate with a Postgraduate Certificate in Creative Arts could apply for credit towards a Postgraduate Diploma in Design, Fine Arts or M?ori Visual Arts, or a relevant Masters programme.  Graduates may, depending on their specialty, find work in a wide range of creative industry, non-governmental and public sector roles. Many creative arts graduates operate their own businesses.","graduateProfile":"NA","educationPathway":"NA","developedBy":"Massey University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=MY0175"},"AU4028":{"i":"AU4028","strategicPurposeStatement":"BMus(Hons) graduates will have undertaken a years specialised study in one of the major subjects, and will have further developed their musical knowledge and understanding and their professional skills.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU4028"},"AU5174":{"i":"AU5174","entryRequirements":"A New Zealand university entrance qualification or an approved alternative. Must meet entry requirements of each component degree. Selection criteria apply.","strategicPurposeStatement":"BA/BFA(Hons) graduates will demonstrate knowledge and understanding of the content and application of Arts disciplines and be critical, reflective practitioners of Fine Arts or design, able to pursue personal professional goals and postgraduate study.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5174"},"VI0031":{"i":"VI0031","entryRequirements":"Bachelor of Music with Honours.","strategicPurposeStatement":"Up to two further years of intensive study in a particular branch of music, following the acquisition of a Bachelor of Music(Honours) degree.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI0031"},"CN0744":{"i":"CN0744","entryRequirements":"An approved Bachelor's degree or equivalent.","strategicPurposeStatement":"Graduates of the Postgraduate Diploma in Illustration will demonstrate a broad and integrated understanding of illustration practice across media, narrative, visual language, and professional strategy. They will be able to generate original work that communicates effectively to a defined audience, articulate a personal artistic vision, and respond critically to the ethical, cultural, and commercial contexts of illustration. Graduates will be prepared for creative roles in illustration-related industries or for advanced study in a Master's programme.","graduateProfile":"A range of assessments will be used including a mix of visual sketchbooks, visual essays, creative project work, written research outputs, portfolios, presentations, and business planning.","developedBy":"University of Canterbury","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=CN0744"},"AK1303":{"i":"AK1303","entryRequirements":"A four-year bachelor's degree or a three-year bachelor's degree plus one year of advanced study. A portfolio of creative writing.","strategicPurposeStatement":"MCW graduates will have produced a sustained work of creative writing under the supervision of an established author.","developedBy":"Auckland University of Technology","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AK1303"},"VI002Y":{"i":"VI002Y","entryRequirements":"A bachelor's degree in design, film, music or theatre, with a B grade average, or equivalent.","strategicPurposeStatement":"Graduates will have the combination of well-developed critical, creative and practical skills that are required for the creative industries, as well as a specialised understanding of their chosen field.  They will demonstrate intellectual autonomy and, using their ability to communicate complex ideas, will be able to coordinate and cooperate with others.  They will have the skills to transition successfully into the workforce as self-employed artists in the fields of design, film, music and theatre or related areas.  Exceptional graduates, with appropriate additional advanced research training, may be able to continue to doctoral studies.","graduateProfile":"NA","educationPathway":"NA","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI002Y"},"WI0900":{"i":"WI0900","entryRequirements":"A relevant bachelors degree","strategicPurposeStatement":"The BMCT(Hons) degree combines taught and collaborative research components focused on creative research skills, critical thinking and advanced expertise in creative technologies: Graduates will have advanced knowledge, understanding and creative skills in at least one of the subject areas offered for the degree. They will understand and be able to reflect upon and critically analyse theory in action and to apply research methods in creative practice and technologies to engage in supervised research in the area of their chosen discipline. Graduates will be prepared to study at higher levels or to pursue creative careers in a wide range of commercial industries and public organisations, both nationally and internationally.","developedBy":"University of Waikato","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=WI0900"},"CN0734":{"i":"CN0734","entryRequirements":"An approved Bachelor's degree or equivalent.","strategicPurposeStatement":"The Postgraduate Diploma in Strategic Communication enables students to analyse others' communication practice and reflect on their own in specific strategic communication contexts such as international relations, crisis management, internal communication, team development, and ethical conundrums. The Diploma extends students' knowledge of theories of strategic, organisational, and public communication as well as Maori and Pacific approaches to communication.","graduateProfile":"A range of assessments will be used including case study analysis; reflection on data collection and analysis; personal reflection; and presentations.","developedBy":"University of Canterbury","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=CN0734"},"WI0910":{"i":"WI0910","entryRequirements":"Bachelor of Media and Creative Technologies or equivalent.","strategicPurposeStatement":"The MMCT degree combines a substantive collaborative research project and an individual research dissertation in the relevant field combined with advanced-level tuition in academic research and vocational skills. Graduates will have advanced knowledge, understanding and creative skills in at least one of the subject areas offered for the degree. They will understand and be able to reflect upon and critically analyse creative theory and to apply research methods in creative practice and technologies to engage in supervised research in the area of their chosen discipline.     Graduates will be prepared to study at higher levels or to pursue creative careers in a wide range of commercial industries and public organisations, both nationally and internationally.  Research outputs with a creative focus are accompanied by theoretical, methodological and technical training appropriate to professional careers and postgraduate study. Graduates will be able to carry out independent, original research and will have advanced creative research skills, professional aptitude and advanced expertise in creative technologies. Graduates will be prepared for study and research at higher levels or to pursue creative and managerial careers in a wide range of commercial industries and public organisations, both nationally and internationally.","developedBy":"University of Waikato","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=WI0910"},"CN0776":{"i":"CN0776","entryRequirements":"An approved Bachelor's degree or equivalent.","strategicPurposeStatement":"Graduates of the Master of Virtual Production will be accomplished creative practitioners capable of producing innovative screen-based work using real-time technologies and virtual production methods. They will demonstrate advanced technical proficiency alongside strong capabilities in visual storytelling. Through applied project work, critical reflection and industry engagement, graduates will be equipped to contribute meaningfully to the evolving screen industries.","graduateProfile":"A range of assessments will be used including treatments, loglines, and critical analysis reports that demonstrate narrative development, audience awareness, and industry context. Also: moodboards, tone frames, storyboards, and annotated scripts that communicate visual tone, design strategy, and scene planning. Project planning and production documentation, team collaboration plans and pitch presentations (live or recorded) simulating industry-standard communication and leadership practices and a final capstone screen work developed using real-time tools and production environments and a substantial written reflection that contextualises the student's project within academic, cultural, and professional discourse.","developedBy":"University of Canterbury","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=CN0776"},"CN0506":{"i":"CN0506","entryRequirements":"Bachelor of Music with Honours.","strategicPurposeStatement":"Graduates of this degree will be composers and performers at highly advanced levels, delivering original/creative work through public recital or portfolio of compositions.","developedBy":"University of Canterbury","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=CN0506"},"AK1327":{"i":"AK1327","entryRequirements":"A relevant Bachelor's degree or equivalent completed with a B grade average or higher in the papers at level 7 or above.","strategicPurposeStatement":"Master of Visual Arts graduates will be creative practitioners and researchers who have advanced knowledge and understanding in their field. They will significantly contribute to the creative sector through critical enquiry and innovative practice. As highly skilled, and innovative creative practitioners their expertise will contribute and respond to, the arts environment locally, nationally and globally. They will have demonstrated the ability to engage in a sustained period of research, and may progress to further study at doctoral level.","graduateProfile":"NA","educationPathway":"NA","developedBy":"Auckland University of Technology","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AK1327"},"VI004G":{"i":"VI004G","entryRequirements":"A Bachelor's degree in a relevant subject with an average grade of B or better. Relevant subjects include communication, journalism, cultural studies, film, media studies, music, marketing, public relations, language and literary studies, and science.","strategicPurposeStatement":"Postgraduate Certificate in Communication graduates will have an understanding of the underpinning key principles of communication and be able to critically analyse communication processes from multiple perspectives in a range of different domains. They will have the skills necessary to debate complex issues related to communication in a constructive and rational manner. Graduates will be able to communicate this knowledge in multiple contexts, using a variety of methods (e.g., written, oral, audio-visual)..  Students who complete the requirements of the PGCertC may be able to continue to the Postgraduate Diploma of Communication or the Master of Communication.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI004G"},"WI0253":{"i":"WI0253","entryRequirements":"Bachelor of Music with Honours degree or equivalent.","strategicPurposeStatement":"Graduates will have developed significant individual motivation in working through and completing substantial tasks in performance (a demonstrated ability to plan, prepare and present a complete musical recital in public) or composition (a demonstrated ability to create a substantial body of original music written to a professional standard, with each piece worthy and capable of being played in public concert or equivalent forum).","developedBy":"University of Waikato","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=WI0253"},"MY0372":{"i":"MY0372","entryRequirements":"A relevant Bachelor's degree with a minimum B average in the highest level courses, or equivalent.","strategicPurposeStatement":"Graduates will apply research, artistic and professional strategies intrinsic to creative disciplines to develop and commercialise their creative practice.  The programme aims are driven by desired graduate attributes that fuse critical, technical and professional skills and knowledge.","developedBy":"Massey University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=MY0372"},"AK1314":{"i":"AK1314","entryRequirements":"A relevant bachelor's degree completed to a merit standard. Applicants may be required to submit a portfolio of work and/or attend a selection interview.","strategicPurposeStatement":"MPMA graduates will be performance and media arts practitioners and researchers who have advanced knowledge and understanding in their field. They will have demonstrated the ability to engage in a sustained period of research and create innovative and unique performative works. They may progress to further study at doctoral level.","developedBy":"Auckland University of Technology","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AK1314"},"MY0025":{"i":"MY0025","entryRequirements":"A New Zealand University Entrance Qualification or equivalent plus a portfolio of work.","strategicPurposeStatement":"Bachelor of Design (Honours) graduates will design in a critically-informed, theoretically underpinned and reflective way, utilising design processes that involve design research processes, analysis, evaluation and synthesis. They will combine a high level of technical proficiency in their specialisation with intellectual and conceptual rigour, respond creatively to client requirements and demonstrate innovative ways to meet their needs, and demonstrate grounding in business and professional practice. Graduates will be effective communicators, express identity through design, demonstrate respect for cultural differences, ability to embrace cultural diversity, and appreciate the distinctive characteristics of Aotearoa/New Zealand in the wider global context. They will critically evaluate their own performance and the work of others, demonstrate personal and professional integrity, an awareness of ethical issues and will operate in a professional manner. They will acknowledge and consider matters of sustainability and adapt to changing environments and conditions. Graduates will undertake and present the results of research projects in which they apply a range of design research methods to result in creative solutions to design problems. Through practice and scholarship they will be able to contribute to the ongoing development of design as a discipline.","developedBy":"Massey University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=MY0025"},"MY0390":{"i":"MY0390","entryRequirements":"Bachelor of Design or equivalent.","strategicPurposeStatement":"Master of Design graduates will be able to implement the findings of research in design practice; integrate theory and practice and demonstrate a command of research methods as they relate to one or more fields of design such as fashion design, industrial design, interior design, photography, textile design, transport design or visual communication design.","developedBy":"Massey University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=MY0390"},"CN0745":{"i":"CN0745","entryRequirements":"An approved Bachelor's degree or equivalent","strategicPurposeStatement":"Graduates of the Postgraduate Certificate in Illustration will have foundational knowledge of illustration techniques, professional practice, and visual storytelling. They will be able to apply creative and critical thinking in the production of illustrated work, demonstrate emerging authorial voice, and engage with the principles of contemporary illustration as a tool for communication. Graduates will be equipped for entry-level roles in creative industries or for further study in illustration or related fields.","graduateProfile":"A range of assessments will be used including a mix of visual sketchbooks, visual essays, creative project work, written research outputs, portfolios, presentations, and business planning.","developedBy":"University of Canterbury","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=CN0745"},"MY0126":{"i":"MY0126","entryRequirements":"A Bachelor of Bachelor of Communication, with a major in the intended postgraduate subject with a minimum B average over the qualifying 300-level courses and a minimum B average in at least 15 x 300-level credits in the intended secondary postgraduate subject, or equivalent.","strategicPurposeStatement":"Graduates will build on the interdisciplinary approach to the study of communication to an advanced level. They will have a specialised knowledge of two complementary communication disciplines representing both business and humanities approaches to the field. They show intellectual independence through self-directed learning. They will have a sophisticated grasp of the key underlying principles of communication and be able to implement and adapt these principles within a complex and rapidly-changing professional environment. They can undertake supervised research and employ those research methods that encourage cross-disciplinary and inter-sectoral collaboration.","graduateProfile":"Not provided","educationPathway":"Not provided","developedBy":"Massey University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=MY0126"},"AK1299":{"i":"AK1299","entryRequirements":"A relevant bachelor's degree or equivalent.","strategicPurposeStatement":"PgDipCS graduates will have advanced knowledge and skills in their chosen area of professional practice and be able to pursue personal professional goals and further postgraduate study. The emphasis placed on integrating theory and practice will enhance problem solving and analytical skills developed at undergraduate level.","developedBy":"Auckland University of Technology","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AK1299"},"AK1330":{"i":"AK1330","entryRequirements":"Bachelor of Visual Arts or equivalent.","strategicPurposeStatement":"PgCertVA graduates will be critically reflective creative practitioners who have advanced knowledge and understanding in their field. They will be prepared for further postgraduate study.","graduateProfile":"NA","educationPathway":"NA","developedBy":"Auckland University of Technology","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AK1330"},"AU5789":{"i":"AU5789","entryRequirements":"A relevant bachelor's degree or postgraduate diploma with minimum GPA, or equivalent.","strategicPurposeStatement":"Graduates of the Master of Creative Arts Therapy programme will have in-depth understanding of the principles, concepts, and ideas defining Creative Arts Therapy theory and practice, and the mastery of techniques appropriate to their chosen approaches. They will be critical, reflective practitioners and researchers able to pursue personal professional goals, including professional registration, and higher postgraduate study.?","graduateProfile":"Assessment modes include: essays, portfolios, practical demonstrations, presentations, research essays.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5789"},"AK1335":{"i":"AK1335","entryRequirements":"In order to be admitted to the Master of Cultural and Creative Practice an applicant must have completed a bachelor's degree or equivalent qualification with a B grade average in the papers at level 7 or above.","strategicPurposeStatement":"Graduates will be critically reflective enterprising practitioners who have advanced knowledge and understanding in their chosen field of cultural and creative practice. They will contribute to the cultural and creative sectors through applied research capabilities and dynamic approaches to practice, collaborating with others and showing leadership in the development of cultural and creative expression.","graduateProfile":"NA","educationPathway":"NA","developedBy":"Auckland University of Technology","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AK1335"},"AK1336":{"i":"AK1336","entryRequirements":"Bachelor's degree or equivalent","strategicPurposeStatement":"Graduates will be critically reflective practitioners who have advanced knowledge and understanding in their field. They will be prepared for further postgraduate study.","graduateProfile":"NA","educationPathway":"NA","developedBy":"Auckland University of Technology","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AK1336"},"OO0007":{"i":"OO0007","entryRequirements":"Bachelor of Music degree or equivalent","strategicPurposeStatement":"This diploma provides advanced study, plus an introduction to research, in a chosen area of music. Recipients are capable of self-directed learning and intellectual independence, and can proceed to further postgraduate study.","developedBy":"University of Otago","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=OO0007"},"OO0509":{"i":"OO0509","entryRequirements":"A bachelor's degree or equivalent.","strategicPurposeStatement":"Holders of this diploma will have a high-level understanding of science communication theory, will have the ability to think like professional science communicators, and will have created communication resources to add to their portfolio.","graduateProfile":"Not applicable","educationPathway":"Not applicable","developedBy":"University of Otago","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=OO0509"},"OT5069":{"i":"OT5069","entryRequirements":"Applicants must already hold the Bachelor of Visual Arts (level 7) or any equivalent qualification at a Bachelor?s level or any other undergraduate degree in a relevant discipline.\n\r\nExceptional applicants not meeting the entry requirements but with appropriate documented professional experience may also be considered.\n\r\nInternational students must demonstrate that they have equivalent experience/qualifications as domestic students and those, whose first language is not English, must provide evidence of English language competence at IELTS level 6.5 (in all areas of the test).","strategicPurposeStatement":"Graduates will be confident and flexible visual arts practitioners in their chosen studio areas, who can integrate their material and conceptual knowledge in transferable ways within their practices and for the benefit of the employment sector.  They are lifelong learners who are productive, lateral thinkers, effective problem solvers in the wider national and international arena.  Graduands are able to produce a coherent body of studio work and can relate this work to its conceptual underpinnings and its wider community of practice in the field of contemporary art.  Course work in research methodologies and participation in seminars on contemporary practices enable them to bridge the gaps created by special circumstances such as periods of leave from study or changes in study direction.","developedBy":"Otago Polytechnic","qualityAssuredBy":"Quality Assurance Division, NZQA","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=OT5069"},"MY1079":{"i":"MY1079","entryRequirements":"A Bachelor of Communication degree or close equivalent.","strategicPurposeStatement":"Graduates will build on the interdisciplinary approach to the study of communication to a higher level than a BC graduate. They will have a specialised knowledge of two complementary communication disciplines representing both business and humanities approaches to the field. They can critically evaluate and apply theories in diverse academic contexts, particularly those that encourage cross-disciplinary and inter-sectoral collaboration. They will have a good grasp of the key underlying principles of communication and be able to implement and adapt these principles within a rapidly-changing professional environment.","graduateProfile":"Not provided","educationPathway":"Not provided","developedBy":"Massey University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=MY1079"},"OO0008":{"i":"OO0008","entryRequirements":"A Bachelor of Music with Honours degree, Postgraduate Diploma in Music, or equivalent.","strategicPurposeStatement":"Graduates will have advanced musical ability and be able to compose, perform, or produce music to internationally recognised standards.","developedBy":"University of Otago","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=OO0008"},"AK1331":{"i":"AK1331","entryRequirements":"Bachelor of Design or equivalent.","strategicPurposeStatement":"PgCertDes graduates will be critically reflective designers who have advanced knowledge and understanding in their field. They will be prepared for further postgraduate study.","graduateProfile":"NA","educationPathway":"NA","developedBy":"Auckland University of Technology","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AK1331"},"CN0714":{"i":"CN0714","entryRequirements":"An approved fine arts Bachelor's degree.","strategicPurposeStatement":"Graduates will have enhanced their skills and knowledge in their first fine arts degree and have acquired technical and theoretical knowledge in their chosen studio discipline and a critical understanding of key principles underpinning their artistic practice.","graduateProfile":"NA","educationPathway":"NA","developedBy":"University of Canterbury","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=CN0714"},"AK1092":{"i":"AK1092","entryRequirements":"A bachelor's degree with a B grade average in courses at level 7 or equivalent.  In exceptional circumstances an applicant may be admitted on the basis of extensive professional and/or scholarly experience deemed equivalent to a bachelor's degree.","strategicPurposeStatement":"MCIT graduates will possess advanced creative, strategic, and contextual skills to navigate technological disruption and drive impactful innovation within complex environments. They will be critical and reflective practitioners with strong applied innovation capability, able to critically engage with emerging transformational creative technologies and apply future-focused thinking to shape ethical and impactful solutions by integrating social, cultural (including Maori and Indigenous), environmental, and political contexts. They will demonstrate the ability to develop entrepreneurial approaches and translate creative concepts into viable initiatives for real-world implementation. Graduates may progress to further postgraduate study or demonstrate leadership in driving creative innovation and technological adaptation within their professional practice.","graduateProfile":"Case analyses, digital portfolios, reflective journals, and scenario responses. Real-world problem-solving, research-informed inquiry, and professional dissemination of outcomes.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AK1092"},"AU5173":{"i":"AU5173","entryRequirements":"Admission on the basis of achievement in the first three years of the BFA (normally a B+ average).","strategicPurposeStatement":"BFA(Hons) graduates will be informed practitioners in the Fine Arts or Design, demonstrating an advanced level of knowledge and achievement. They will be critical, reflective practitioners able to pursue personal professional goals and postgraduate study.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5173"},"VI00Y5":{"i":"VI00Y5","entryRequirements":"A Victoria University of Wellington bachelor's degree (or graduate diploma) in design, or equivalent from another university.","strategicPurposeStatement":"Graduates will be able to apply critical and creative thinking to design problems and will be able to work as part of a team as well as independently. They will find employment or enhance their existing employability in areas such as industrial design, product design, additive manufacturing, game design, visual effects and post-production, interaction design, UI/UX design, usability, exhibition design, service design, advertising and design research. Some graduates may be able to progress to doctoral study in design.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI00Y5"},"OO0006":{"i":"OO0006","entryRequirements":"A Bachelor of Music degree with an average grade of at least B+ in the final year of study; or equivalent.","strategicPurposeStatement":"Graduates of this degree programme are able to pursue professional music careers and further study at postgraduate level.","developedBy":"University of Otago","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=OO0006"},"CN0774":{"i":"CN0774","entryRequirements":"An approved Bachelor's degree or equivalent.","strategicPurposeStatement":"Graduates of the Postgraduate Diploma in Virtual Production will possess the creative, technical, and collaborative skills required to contribute to real-time screen production environments. They will be equipped to develop original story concepts, design visual worlds, and produce short-form digital outputs using industry-standard virtual production tools. Through practice-based learning and team collaboration, graduates will gain a working knowledge of virtual production pipelines and workflows, and apply ethical, inclusive, and culturally responsive approaches in creative settings. This qualification prepares students for professional roles or further study at master's level.","graduateProfile":"A range of assessments will be used including written concept and research work, the creation of visual and design artefacts, project planning and production documentation, team collaboration plans and pitch presentations (live or recorded) simulating industry-standard communication and leadership practices and a final capstone screen work developed using real-time tools and production environments.","developedBy":"University of Canterbury","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=CN0774"},"MY0052":{"i":"MY0052","entryRequirements":"1. Admission to the Bachelor of Creative Media Production Honours requires that the candidate will:    (a) meet the University admission requirements as specified; and    (b) have been awarded or qualified for a Bachelor of Creative Media Production, having achieved at least a B grade average over the highest level courses, or equivalent.","strategicPurposeStatement":"The Bachelor of Creative Media Production (Honours) aims to provide an advanced?professional education in a research-led multidisciplinary programme of study that equips graduates to operate in a range of roles in creative media production industries with these five defining attributes:    Creativity -?Toi; Virtuosity - Mohio; Understanding - Matauranga; Autonomy -?Mana; Connectedness?- Whanaungatanga.    Through both specialist and transferable knowledge and skills, the Bachelor of Creative Media Production (Honours) degree will enable graduates to make wide-ranging cultural, social and economic contributions to society.","developedBy":"Massey University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=MY0052"},"VI00X1":{"i":"VI00X1","entryRequirements":"(i) completed a Master of Music with First Class Honours (or Second Class Honours, Division 1) or Master of Musical Arts with Distinction or Merit; (ii) passed an audition, in the case of a candidate in performance, or submitted an acceptable portfolio","strategicPurposeStatement":"This new qualification is proposed specifically as a way to foster postgraduate research in creative work, in accordance both with international standards and degree paths in New Zealand. The three-year degree is put forward in two parts, Part One consisting of a provisional year comprising 30 pts of coursework, 30 pts of research proposal development (including a public presentation), and 60pts of portfolio/public performance, and Part Two consisting of a 240 pt thesis.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI00X1"},"VI004E":{"i":"VI004E","entryRequirements":"A Bachelor's degree in a relevant subject with an average grade of B or better. Relevant subjects include communication, journalism, cultural studies, film, media studies, music, marketing, public relations, language and literary studies, and science.","strategicPurposeStatement":"Students who graduate with a Master of Communication will have meta-theoretical analytical skills that allow them to carry out their own research on communication-related issues. Graduates will be able to critically analyse communication processes from multiple perspectives in a range of different domains and work across different public and private sectors, particularly in communication-related industries and institutions. They will have the skills necessary to debate complex issues related to communication in a constructive and rational manner. Graduates will also be able to communicate this knowledge in multiple contexts, using a variety of methods (e.g., written, oral, audio-visual), as well as maintain and promote intellectual integrity and ethical practices during the production of communication research, including tikanga Maori. They will be well-prepared to take on leadership roles in communications and media-related industries and institutions. Depending on their overall GPA, graduates may also be able to continue to doctoral study in communication or cognate fields. Students who have completed COMS 590 Internship or SCIS 589 Science Communication Project will have relevant skills and understanding from experience of communications in the practical workplace.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI004E"},"AK3696":{"i":"AK3696","entryRequirements":"A relevant Bachelors degree with a B+ grade average or better.","strategicPurposeStatement":"Graduates will have a broad range of research skills together with sound analytical thinking skills which will enable them to critically evaluate and apply relevant literature and research in their arts discipline.","developedBy":"Auckland University of Technology","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AK3696"},"CN0172":{"i":"CN0172","entryRequirements":"An approved New Zealand University Entrance qualification or equivalent.","strategicPurposeStatement":"Graduates will have the conceptual and theoretical knowledge, including Indigenous knowledge/matauranga Maori, and the creative and technical skills and experience to excel across the digital screen industries of film making, screenwriting, screen sound, game arts, game development, and animation. As well as focused expertise in a specific discipline, graduates will be positioned at the forefront of the convergence of these digital screen industries, by working in cross-disciplinary teams to produce collaborative creative outputs. Graduates will be skilled storytellers, who can translate their vision onto the digital screen using industry standard tools.","graduateProfile":"A range of assessments will be used including coursework, assignments, presentations, group work, projects, reflections and proposals.","developedBy":"University of Canterbury","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=CN0172"},"VI003A":{"i":"VI003A","entryRequirements":"A bachelor's degree in a field other than media design, with an average grade of B or better.","strategicPurposeStatement":"Graduates will be able to formulate and develop creative strategies, independently research and use design technologies and tools, and develop practical interaction design or user-experience design solutions. They will have a mastery of design thinking and studio processes that will prepare them for professional work in the creative IT industry. They will demonstrate teamwork and written and oral communication skills.  Graduates may also be able to progress to a research-based master's degree.","graduateProfile":"NA","educationPathway":"NA","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI003A"},"MY0252":{"i":"MY0252","entryRequirements":"Appropriate degree or equivalent, plus a portfolio of work and appropriate experience.","strategicPurposeStatement":"Graduates will acquire, evaluate and apply knowledge appropriately, critically and creatively, be effective communicators, and apply ethical standards appropriate to their discipline. They will approach design in a critically-informed, theoretically underpinned and reflective way. They will utilise design processes that involve analysis, evaluation and synthesis, evaluate research methods to determine their potential for the resolution of design problems, apply critical understanding of discourses and research relevant to contemporary practices in design. They will be capable of designing research projects, carrying out literature searches, critically evaluating their own work, and presenting outcomes in a professional manner.","developedBy":"Massey University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=MY0252"},"AU5535":{"i":"AU5535","entryRequirements":"Postgraduate Diploma in Dance Studies, Bachelor of Dance Studies (Honours) or an equivalent qualification","strategicPurposeStatement":"Graduates of the MCommDance programme will have in-depth knowledge of a selected field of community dance, and the mastery of methodologies appropriate to their chosen enquiry. They will have a high level of competency in discussing and making connections between various aspects of current practices and relevant historical, theoretical and cultural aspects related to their area of community dance research. It is intended that students will be equipped to pursue careers in a range of community dance and arts related professions as well as being prepared for doctoral level study.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5535"},"AU5156":{"i":"AU5156","entryRequirements":"Bachelor of Performing Arts or equivalent degree, or the attainment of a level of competence considered equivalent to a degree and appropriate for a specialisation listed in the diploma.","strategicPurposeStatement":"PGDipCPA graduates will have achieved advanced skills and knowledge in their specialisation, as well as developing a critical and theoretical understanding in the specialisation and the ability to undertake research at masters' level.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5156"},"AU5756":{"i":"AU5756","entryRequirements":"Completed a relevant Bachelors degree with a minimum GPA.","strategicPurposeStatement":"MC graduates will have developed advanced competencies that are highly valued across a broad range of employment sectors. Graduates will be well-prepared for leadership roles in communication professions, including media, public relations, and advertising. Students will also be well-placed to take on leadership roles across a wide range of public, private and social organisations in which advanced communication skills are highly sought-after, including: government agencies; community and charitable organisations; for-profit and not-for-profit enterprises; and civil society organisations. Whichever sector they work in, the distinctive character of this programme will empower graduates to become influential agents of positive social change. Graduates from the MC programme will also be qualified and well-prepared to enter international or domestic doctoral programmes in Communication.","graduateProfile":"Assessment methods include coursework assignments, projects, dissertation and exams.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5756"},"AU5591":{"i":"AU5591","entryRequirements":"A relevant bachelor's degree, or postgraduate diploma, or the equivalent; a minimum GPA;  and a successful interview.  Selection criteria apply.","strategicPurposeStatement":"MDMT graduates will know and understand the principles, concepts and ideas that define the professional practice of Dance Movement Therapy. They will be informed, responsive professional practitioners able to contribute to the wellbeing of their communities through awareness of a range of therapeutic practices.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5591"},"AK1093":{"i":"AK1093","entryRequirements":"Bachelor's degree or equivalent.","strategicPurposeStatement":"PgDipCIT graduates will have the skills to respond to change and create meaningful ideas using new technologies. They will be thoughtful and practical, able to work with emerging tools and think ahead to develop ethical and useful solutions that consider social, cultural (including Maori and Indigenous), environmental, and political factors. They will know how to turn creative ideas into real-world projects and may go on to further study or take on leadership roles in their field.","graduateProfile":"Case analyses, digital portfolios, reflective journals, and scenario responses.","developedBy":"Auckland University of Technology","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AK1093"},"MY0437":{"i":"MY0437","entryRequirements":"A Bachelor of Communication degree, or close equivalent.","strategicPurposeStatement":"Graduates will possess an in-depth understanding of the corpus of theoretical and applied subjects pertinent to communication studies at postgraduate level. They will be familiar with standard expectations of how enquiry in communication is normally conducted and creative in their approach to research design and problem-solving.","graduateProfile":"Not provided","educationPathway":"Not provided","developedBy":"Massey University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=MY0437"},"CN0502":{"i":"CN0502","entryRequirements":"Bachelor of Music","strategicPurposeStatement":"Graduates will be experienced in independent musical study with advanced understanding and skills in their specialist areas, including music performance, composition, musicology, musicianship, jazz, digital music, musical aesthetics, ethnomusicology and music education. Graduates of music are found in a wide range of occupations including positions in schools, conservatories, universities, orchestras, opera houses and libraries, and in hospitals as music therapists. They are prominent in areas of musical leadership with community groups such as choirs and orchestras. Graduates also work in fields such as journalism, television and radio (planning as well as production), and publishing, and in technical areas including recording.","developedBy":"University of Canterbury","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=CN0502"},"AU5136":{"i":"AU5136","entryRequirements":"Degree of Master of Music with First Class honours or Second Class Honours Division One","strategicPurposeStatement":"A DMA graduate will be a high-profile performing musician capable of pursuing a professional career as a soloist, teacher, broadcaster and recording artist. His or her performances will be characterised by highly developed technique and musical insights, research-based knowledge of a wide repertoire, and an understanding of current trends and issues.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5136"},"WI0940":{"i":"WI0940","entryRequirements":"Bachelors degree or equivalent, completed at a specified minimum level of attainment.","strategicPurposeStatement":"Graduates will be effective writers who understand genre, audience, and register, and the conventions of the various writing communities within which they are working.  They will be able to engage thoughtfully and critically within their own and other people's writing, and have a knowledge of the verbal, grammatical and analytical skills that excellent academic and creative writing require. They will have the ability to think critically and communicate well, especially in text-based formats.  They will have high-level skills as readers, writers and editors of their own and other people's work, and will be able to produce excellent writing in a range of forms and genres, They will be independent and self-directed, and will be able to carry a major writing project from inception to completion.","graduateProfile":"NA","educationPathway":"NA","developedBy":"University of Waikato","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=WI0940"},"AK3670":{"i":"AK3670","entryRequirements":"A relevant bachelor's degree completed to a merit standard.","strategicPurposeStatement":"BArtDes(Hons) graduates will be advanced and reflexive art and design practitioners, able to undertake research in their specialist area. They will be able to produce, articulate and evaluate practical and contextual issues in art and design. They will be prepared for further postgraduate study at master's or doctoral level.","developedBy":"Auckland University of Technology","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AK3670"},"OT4989":{"i":"OT4989","entryRequirements":"1.1.1\tEntry Criteria\n\r\nMinimum academic entry criteria are:\n\r\n*\tApplicants must hold an accredited undergraduate degree in design (or design-related discipline), or equivalent recognised qualification and/or experience (all transcripts are required to be certified)\n\r\n*\tApplicants must have industry-related experience, working in business, production or design related work (Curriculum Vitae required)\n\r\n*\tApplicants must present a portfolio of work with their application that demonstrates visually, the applicant's design ability and enterprise interest or aspiration. The portfolio will be comprised of words and images in digital format\n\r\n*\tLetter of introduction and a proposal which outlines your major project focus for the Master of Design Enterprise\n\r\n*\tName and contact details of two referees\n\r\n1.1.2\tInternational applicants\n\r\nMinimum academic entry criteria are:\n\r\n*\tApplicants must hold an accredited undergraduate degree in design (or design-related discipline), or equivalent recognised qualification and/or experience (all transcripts are required to be certified)\n\r\n*\tApplicants must have industry-related experience, working in business, production or design related work (Curriculum Vitae required)\n\r\n*\tApplicants must present a portfolio of work with their application that demonstrates visually, the applicant's design ability and enterprise interest or aspiration. The portfolio will be comprised of words and images in digital format\n\r\n*\tLetter of introduction and a proposal which outlines your major project focus for the Master of Design Enterprise\n\r\n*\tName and contact details of two referees\n\r\n*\tEnglish Language Requirements: Applicants must have achieved an overall band score (Academic) of 6.5 IELTS, with no individual score less than 6.5 or equivalent or TOEFL 600 paper, 237-250 computer, TWE 5. \n\r\nEnglish language requirements for students from non-English speaking backgrounds\n\r\nIn addition to meeting the same entry criteria as those listed above, those for whom English is a second language must also meet the International English Language Testing System (IELTS) (academic version) language requirements listed below\n\r\n*\tOverall band score (Academic) of 6.5 IELTS with no individual score less than 6.0 or equivalent.","strategicPurposeStatement":"Graduates have attained a recognised post graduate qualification suitable to allow entry to careers within product and service providing industry that require design and design-driven strategy expertise within an organisation or enterprise, in situations such as: - New product and service design, redesign or modification - New product/service design-led strategic planning and implementation. - Design-led innovation and implementation of new technologies in products. - Multi-disciplinary design team leadership. - Intrapreneurial new product/service venture within an organisation. As well as being qualified for entry into employment, the graduates of the Master of Product Design Enterprise will be suitably qualified for: - Undertaking further post graduate study. - Engaging in design driven entrepreneurial venture. - Design-led enterprise advocacy, strategic design implementation and education roles.","graduateProfile":"Students who complete all the academic requirements of years one and two of the masters degree programme are eligible to graduate as Master of Design Enterprise.\n\r\nGraduates have attained a recognised post graduate qualification suitable to allow entry to careers within product and service providing industry  that require design and design-driven strategy expertise within an organisation or enterprise, in situations such as:\n\r\n*\tNew product and service design, redesign or modification\n\r\n*\tNew product/service design-led strategic planning and implementation.\n\r\n*\tDesign-led innovation and implementation of new technologies in products/services.\n\r\n*\tMulti-disciplinary design team leadership.\n\r\n*\tEntrepreneurial new product/service venture within an organisation.\n\n\n\r\nAs well as being qualified for entry into employment, the graduates of the Master of Design Enterprise will be suitably qualified for:\n\r\n*\tUndertaking further post graduate study.\n\r\n*\tEngaging in design driven entrepreneurial venture.\n\r\n*\tDesign-led enterprise advocacy, strategic design implementation and education roles","educationPathway":"While the MDE will be encouraging multi-disciplinary design graduates of all New Zealand and overseas design schools to apply for entry to the programme, the undergraduate degree design programmes within the department of design at Otago Polytechnic, provide a natural bridging option into the programme, following a post-graduation period of industry work experience in design or business.","developedBy":"Otago Polytechnic","qualityAssuredBy":"Quality Assurance Division, NZQA","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=OT4989"},"AU5145":{"i":"AU5145","entryRequirements":"A four-year bachelor's degree, a bachelor's (honours) degree, or a bachelor's degree and either a professional qualification equivalent to one years advanced study or at least three years of relevant professional experience. Portfolio required.","strategicPurposeStatement":"MCW graduates will have developed skills in analysing critically and editing their own creative writing, skills that are transferable to other genres of writing.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5145"},"AK1328":{"i":"AK1328","entryRequirements":"A relevant Bachelor's Degree or equivalent completed with a B grade average or higher in the papers at level 7 or above.","strategicPurposeStatement":"Master of Design graduates will have advanced knowledge and understanding in their chosen field such as digital, textile, fashion, spatial, communication or product design. Through applied research capability they will possess critical and reflective skills expected of design professionals. As highly skilled, confident and innovative practitioners their expertise will contribute to, as well as respond to, the rapidly changing environment of the creative industries. They will have demonstrated the ability to engage in a sustained period of research, and may progress to further study at doctoral level.","graduateProfile":"NA","educationPathway":"NA","developedBy":"Auckland University of Technology","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AK1328"},"AK1326":{"i":"AK1326","entryRequirements":"A relevant bachelor's degree or equivalent.","strategicPurposeStatement":"Graduates will have an advanced body of knowledge in the discipline of brand communication, combined with the ability to apply this knowledge in a variety of industry sectors. They will be reflective practitioners who have independence of thought and self- direction necessary for continuing their learning and professional development. Graduates will have a well-rounded appreciation of the bicultural and multicultural nature of communication in New Zealand and around the world.","developedBy":"Auckland University of Technology","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AK1326"},"OT5068":{"i":"OT5068","entryRequirements":"Applicants must already hold the Bachelor of Visual Arts (level 7) or any equivalent qualification at a Bachelor?s level or any other undergraduate degree in a relevant discipline.\n\r\nExceptional applicants not meeting the entry requirements but with appropriate documented professional experience may also be considered.\n\r\nInternational students must demonstrate that they have equivalent experience/qualifications as domestic students and for those whose first language is not English, must provide evidence of English language competence at IELTS level 6.5 (in all areas of the test).","strategicPurposeStatement":"Graduates will be confident and flexible visual arts practitioners in their chosen studio areas, who can integrate their material and conceptual knowledge in transferable ways within their practices and for the benefit of the employment sector.  They are lifelong learners who are productive, lateral thinkers, effective problem solvers in the wider national and international arena.  Graduands are able to produce a coherent proposal for studio work with associated practical examples and can relate this work to its conceptual underpinnings and its wider community of practice in the field of contemporary art.  Course work in research methodologies and participation in seminars on contemporary practices enable them to bridge the gaps created by special circumstances such as periods of leave from study or changes in study direction.","developedBy":"Otago Polytechnic","qualityAssuredBy":"Quality Assurance Division, NZQA","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=OT5068"},"AU0395":{"i":"AU0395","entryRequirements":"A Bachelor of Fine Arts or Bachelor of Fine Arts (Honours) or Postgraduate Diploma in Fine Arts, or an approved equivalent qualification, and a minimum Grade Point Average (GPA).","strategicPurposeStatement":"MFA graduates will have the ability to develop and sustain critically driven, research informed original creative positions and practices. They will have an in-depth, working knowledge of a selected field of specialised research and practice in contemporary art, and a mastery of methodologies appropriate to their chosen enquiry. They will be equipped to pursue careers in a range of creative industries and prepared for doctoral level study.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU0395"},"WI0143":{"i":"WI0143","entryRequirements":"Bachelor of Communication Studies degree of The University of Waikato or equivalent.","strategicPurposeStatement":"Graduates will be good communication practioners, with an in-depth understanding of the responsibilities of the media and communication industries in local, national, and global contexts, and the impacts of communication on individuals, groups and social culture. They will be equipped to present, evaluate, and interpret qualitative data and to apply current theories in their areas of specialisation to a high level of sophistication.","developedBy":"University of Waikato","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=WI0143"},"WA2161":{"i":"WA2161","entryRequirements":"Bachelors degree or equivalent experience or qualifications. \n\r\nMinimum entry for international students of IELTS (or equivalent) Level 6.5.","strategicPurposeStatement":"Students will develop applied skills and expertise in their chosen area of specialisation. Students will gain a computer graphic design qualification which enables a variety of employment opportunities in design and technology.","graduateProfile":"Self-directed research and assigned projects are used \n\r\nto develop an individually negotiated programme of \n\r\nstudy that will provide the opportunity to broaden your \n\r\nunderstanding of the design profession and expose you to \n\r\ncurrent thinking and research methodologies.","educationPathway":"Further studies in related areas","developedBy":"Universal College of Learning (UCOL)","qualityAssuredBy":"New Zealand Qualifications Authority","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=WA2161"},"VI00A7":{"i":"VI00A7","entryRequirements":"A Bachelor of Design or Bachelor of Design (Hons)  or approved equivalent or appropriate experience.","strategicPurposeStatement":"A Master of Design graduate will have developed analytical, critical, problem-solving, and research skills and obtained an advanced understanding of a specialist field of design.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI00A7"},"OO0479":{"i":"OO0479","entryRequirements":"A bachelor's degree with first or upper second class honours, a master's degree, or equivalent.","strategicPurposeStatement":"Graduates will have the ability to create or perform musical works at the highest professional level, and to contribute at an advanced level to the development of musical skills and understanding in the community.","developedBy":"University of Otago","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=OO0479"},"MY0257":{"i":"MY0257","entryRequirements":"A Bachelors degree or equivalent, with at least a B grade average in the 300-level majoring papers or equivalent; and been selected into the programme on the basis of a written application and interview.","strategicPurposeStatement":"Graduates will have the key competencies expected of them as new recruits in the journalism industry, including high quality news gathering and investigative abilities, the capacity to disseminate such investigations in the form of journalism, a critical understanding of media law and ethics, the taking of shorthand, conducting and writing up a major piece of investigative journalism, and creatively preparing news copy for non-print media platforms, such as radio, television and the internet, and critically reflecting on new media practices including the use of social media. Students will demonstrate an ability to take news photography and understand relevant economics and statistical concepts. Graduates will also be able to critically reflect on their reporting activities, including journalisms historical and contemporary role in society, and the students own experiences in finding and publishing journalism, including news reporting and investigative journalism. Graduates will be ready to take up employment, via the programmes strong connections with the journalism industry, including its industry liaison committee and emphasis on student work internships.","developedBy":"Massey University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=MY0257"},"VI00W8":{"i":"VI00W8","entryRequirements":"Bachelor of Music with First or 2(1) Honours or a Postgraduate Diploma in Music with Distinction or Merit; and either audition (Performance) or acceptable portfolio of compositions (Composition) or sound-based works (Sonic Arts).","strategicPurposeStatement":"Postgraduate research in creative work (composition, sonic arts and performance) of international standard.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI00W8"},"CN0706":{"i":"CN0706","entryRequirements":"Bachelor of Fine Arts with Honours","strategicPurposeStatement":"Graduates will have extended their knowledge and skill as professional visual artists through a period of intensive studio practice, guided by professional tutorial support and supervision. Graduates will be prepared for specific professions such as graphic design and film making have the skills and attitude necessary to successfully practise as artists and scholars in their individual areas of expertise.","developedBy":"University of Canterbury","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=CN0706"},"VI003W":{"i":"VI003W","entryRequirements":"A bachelor's degree in a relevant subject, with a B grade average or better, and evidence of proficiency in at least one language other than English to the equivalent of at least 40 300-level points, with a B grade average or better. Examples of relevant subjects include a language other than English and intercultural communication studies.","strategicPurposeStatement":"Graduates will acquire the theoretical and practical set of skills necessary to be cross-culturally competent as well as opportunities and platforms to apply them through the most powerful form of intercultural communication: translation. These skills are in high demand among employers across a wide range of areas, including business (international trade, advertising, website localisation, hospitality and tourism), education (second language learning, multicultural instruction, international relations, development studies, digital humanities, medical humanities, literature and linguistics), and the creative industries (film production, subtitling and dubbing, graphic design, creative writing, advertising). Graduates will be able to successfully acquire, analyse, interpret, negotiate and reproduce information and data across linguistic, cultural, and socio-political contexts.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI003W"},"AU0396":{"i":"AU0396","entryRequirements":"Completed the requirements for a Bachelor of Dance Studies or Bachelor of Dance Studies (Honours), Postgraduate Diploma in Creative and Performing Arts, or Postgraduate Diploma in Dance Studies, with a minimum Grade Point Average (GPA) or  extensive relevant practical, professional or scholarly experience.","strategicPurposeStatement":"MCPA graduates will have achieved a high level of training in the creative and performing arts enabling them to pursue careers in performance, production and arts management.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU0396"},"MY0441":{"i":"MY0441","entryRequirements":"A Bachelors degree or equivalent, with at least a B grade average in the 300-level majoring papers or equivalent; and been selected into the programme on the basis of a written application and interview","strategicPurposeStatement":"Graduates will be able to gather and write journalism of significance and substance, and be able to critically reflect on that journalism, informed by the appropriate academic literature. They will be competent independent researchers who have demonstrated the ability to critically analyse and evaluate evidence and ideas, interrogate assumptions and practices, and employ appropriate research methodologies, within the context of journalism as a practice discipline, to recognised international standards. Graduates will obtain positions in the journalism industry or, if they already work in the industry, significantly enhance their career prospects.","developedBy":"Massey University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=MY0441"},"OO0462":{"i":"OO0462","entryRequirements":"Bachelor of Science, Bachelor of Arts, or an alternative acceptable qualification.","strategicPurposeStatement":"Graduates will be equipped with specialist skills and theory allowing them to communicate science effectively to a non-specialist audience through film and media, or non-fiction writing.","developedBy":"University of Otago","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=OO0462"},"CN0722":{"i":"CN0722","entryRequirements":"Bachelor of Fine Arts and passes in specified qualifying courses.","strategicPurposeStatement":"Graduates will have a developed capacity for critical thinking and its creative expression and have gained an understanding of the visual arts through an in-depth engagement with and analysis of the creative process. This specialized focus on creativity embodied within the programme imparts to and ennobles graduates with valuable life-long skills in strategic and creative thinking. They will also have advanced technical and theoretical knowledge in their chosen Studio discipline and a critical understanding of key principles underpinning their artistic practice.","developedBy":"University of Canterbury","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=CN0722"},"AU5649":{"i":"AU5649","entryRequirements":"Completed the requirements for the Degree of Bachelor of Music from this University with a minimum Grade point Average (GPA).","strategicPurposeStatement":"Graduates will be equipped to apply their knowledge and understanding in both academic and professional contexts. They will be critical thinkers, able to pursue personal professional goals and confidently able to engage in postgraduate study.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5649"},"WI0139":{"i":"WI0139","entryRequirements":"Bachelor of Music or equivalent.","strategicPurposeStatement":"Graduates will develop an advanced level of musicianship and understand concepts and principles of composition, performance, history and analysis of music.","developedBy":"University of Waikato","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=WI0139"}};
